export const garnierEditions = [{"source_id":"garnier:19800","title":"Actualité de Jeanne Flore","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453243"],"subtitle":"","description":"Les contributions réunies dans ce volume ainsi que l’étude de la réception de Jeanne Flore attestent de la richesse des recherches concernant l’auteur des Comptes amoureux et de l’intérêt de ce texte qui semble toujours, par-delà les siècles, prendre à témoin ses lecteurs.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19745","title":"Ambroise Paré (1510-1590) Pratique et écriture de la science à la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453489"],"subtitle":"","description":"Cet ouvrage collectif éclaire les dimensions littéraire, rhétorique et philosophique des Œuvres complètes d'Ambroise Paré, ainsi que la postérité de ce texte en langue vernaculaire. Est ainsi soulignée la richesse d'une œuvre représentative de l'écriture de la science dans la deuxième moitié du xvie siècle.","from":[{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]}],"paths":[{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]},{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:86","title":"André Suarès et le wagnérisme","authors":["Gagneux, Frédéric"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812441134"],"subtitle":"","description":"André Suarès est profondément marqué par la musique de Richard Wagner ainsi que par ses écrits théoriques sur l’art. Il lit la Revue wagnérienne durant ses années d’École normale supérieure (1886-1889). Le wagnérisme est alors une question littéraire. Avec Wagner, on s’interroge sur la place de l’artiste dans la société, sur la nature de l’art. Comme lui, on veut lier musique et littérature dans une oeuvre totale. Le jeune Suarès s’engage dans de nombreux projets pour la plupart inédits (poésie, romans, théâtre, textes théoriques) et publie son Wagner, en 1899. Cet ouvrage permet de découvrir ces textes inédits de Suarès et d’éclairer son oeuvre en la replaçant dans le contexte","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:104940","title":"Apollinaire, les musiciens et la musique","authors":["Maras, Alessandro"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406123538"],"subtitle":"","description":"La relation d’Apollinaire avec la musique était complexe et contradictoire. Cet ouvrage tente d’explorer les chemins empruntés par le poète qui l’ont conduit à rencontrer la musique de Richard Wagner, le café-concert ou encore Erik Satie, et d’interroger l’héritage que ces rencontres nous ont laissé.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:3403","title":"Bande dessinée et littérature","authors":["Dürrenmatt, Jacques"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812417153"],"subtitle":"","description":"Si certains considèrent la bande dessinée comme un simple genre littéraire, d’autres affirment leurs différences fondamentales, usant d’arguments parfois plus intuitifs que rationnels. Cet ouvrage tente de clarifier ce que chacun des deux arts est susceptible de prendre mais aussi d’apporter à l’autre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Bande dessinée","subcategory":"Études sur la BD","details":["Arts et narration"]}]},{"source_id":"garnier:19501","title":"Bibliographie annotée des ouvrages relatifs à Montaigne - publiés entre 1976 et 1985","authors":["Clive, H.-Peter"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455117"],"subtitle":"","description":"La Bibliographie annotée des ouvrages relatifs à Montaigne (1976-1985) recense 1201 études parues entre 1976 et 1985. Elle fait suite à celle de Pierre Bonnet (Bibliographie méthodique et analytique des ouvrages et documents relatifs à Montaigne). Les études recensées y sont classées par ordre alphabétique et font l'objet d'un résumé analytique. La bibliographie est pourvue d'un index des matières.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19476","title":"Bibliographie méthodique et analytique des ouvrages et documents relatifs à Montaigne","authors":["Bonnet, Pierre"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458217"],"subtitle":"","description":"Dans cette bibliographie de référence Pierre Bonnet donne l'inventaire de 3270 ouvrages relatifs à Montaigne et parus de 1580 à 1975; classés de façon méthodique en vingt et un chapitres. Chaque ouvrage fait l'objet d'un résumé analytique. La bibliographie est pourvue de deux index, des auteurs et des matières.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:97390","title":"Bibliotheca Desaniana Catalogue Montaigne","authors":["Desan, Philippe"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406105855"],"subtitle":"","description":"Avec 202 numéros représentant 161 éditions, le catalogue Montaigne de la Bibliotheca Desaniana contient presque toutes les éditions des œuvres de Montaigne. Chaque entrée comprend la collation de l’exemplaire, une notice sur l’édition, la description de la reliure, les provenances et des reproductions en couleur.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:482","title":"Bibliotheca Desaniana Catalogue Montaigne","authors":["Desan, Philippe"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444272"],"subtitle":"","description":"Avec 186 numéros représentant 148 éditions, le fonds Montaigne de la Bibliotheca Desaniana contient presque toutes les éditions des œuvres de Montaigne, ainsi que les traductions en italien, anglais, néerlandais et allemand jusqu'en 1833. Chaque entrée du catalogue comprend la collation de l'exemplaire, son contenu bibliographique, une notice sur les particularités de l'édition, la description de la reliure, l'identification des provenances et la reproduction en couleur de la page de titre et de la reliure.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19821","title":"Bomarzo ou les incertitudes de la lecture : - Figure de la meraviglia dans un jardin maniériste du XVIe siècle","authors":["Bélanger, Anne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451645"],"subtitle":"","description":"Espace concret et imaginaire, le jardin sollicite à la fois l'esprit, les sens et l'imagination du visiteur. Tous les arts sont réunis dans le jardin, emportant avec eux leurs discours, leurs savoirs et leurs pratiques. Cependant, si cette caractéristique lui confère une remarquable valeur esthétique et épistémologique, elle suppose aussi l'extrême complexité d'un objet qui, de ce fait, se dérobe volontiers à l'analyse. C'est ce que montre de manière exemplaire le bois sacré de Bomarzo, un jardin maniériste italien du XVIe siècle, qui constitue encore, à ce jour, une véritable énigme pour les chercheurs. La lecture du bois sacré proposée ici est intimement liée à une figure, celle de la merveille, mise en lumière grâce à la poétique de la meraviglia du philosophe Francesco Patrizi (15281597). La merveille se caractérise par un mélange de vrai et de faux, de crédible et d'incroyable, de manière à produire le doute et l'incertitude. C'est elle encore qui assure la liaison entre les sens et l'esprit, en sollicitant au passage la mémoire et l'imagination, et en remuant les passions. C'est la merveille enfin qui permet de rendre compte de l'expérience du visiteur du jardin et des effets d'illisibilité et d'incertitude qui surgissent dans son esprit.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Architecture","details":["Histoire / Patrimoine"]}]},{"source_id":"garnier:19635","title":"Calvin et la dynamique de la parole Étude de rhétorique réformée","authors":["Millet, Olivier"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458002"],"subtitle":"","description":"Cet ouvrage situe la culture et la pratique rhétoriques de Calvin dans le cadre de l’humanisme de la Renaissance. Il porte sur la formation de Calvin et la réception française de l’humanisme rhétorique germanique (Melanchthon), sur la rhétorique biblique selon Calvin et sur le passage du latin au français.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Textes sacrés et exégèse"]}]},{"source_id":"garnier:19511","title":"Causeries sur Montaigne","authors":["Sainte-Beuve, Charles-Augustin"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459054"],"subtitle":"","description":"Sainte-Beuve parsème ses œuvres de références à Montaigne. Les affinités entre ces « deux cerveaux congénères » sont indéniables et s'étendent de l'homme à l'écrivain. Cette édition donne un aperçu de la réception de Montaigne au xixe siècle et révèle la richesse des analyses du critique littéraire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:999","title":"Cinéma et théâtre chez Jean Cocteau Intermédialité et esthétique","authors":["Surmann, Caroline"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812440533"],"subtitle":"","description":"Cette étude envisage l’œuvre de Jean Cocteau et plus particulièrement son cinéma à partir d’une perspective intermédiale décrivant comment et pourquoi Cocteau intègre l’autre au cinéma et «impurifie» sa matière. Les questions de l’intermédialité y sont mises en rapport avec des questions relatives à l’esthétique, confrontant l’évolution et l’invention des formes aux réflexions sur la connaissance et la perception du réel qui les ont engendrées.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]}]},{"source_id":"garnier:765","title":"Claudel Danse Japon","authors":["Wasserman, Michel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443992"],"subtitle":"","description":"Conçu pour Nijinski à Rio avant que le danseur ne sombre dans la schizophrénie, le ballet de L'Homme et son désir (argument de Paul Claudel, musique de Darius Milhaud) sera finalement créé en 1921 à Paris par les Ballets Suédois. Il connaîtra ensuite au Japon une improbable mutation, Claudel reprenant dans La Femme et son ombre bien des aspects de son ballet brésilien tout en l'inscrivant, non sans subtilité, dans un cadre emprunté à la tradition des grands acteurs de kabuki qui l'ont approché.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Danse"]}]},{"source_id":"garnier:25562","title":"Commentaire aux poèmes homériques. Tome I","authors":["Sponde, Jean de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406083184"],"subtitle":"","description":"Publié en 1583 avec une édition des poèmes homériques, le commentaire latin de l'Iliade et de l'Odyssée par Jean de Sponde veut montrer la cohérence et l'intérêt stylistique de l'œuvre d'Homère ainsi que les vertus de ses héros. Il est présenté ici dans une édition moderne et accompagné d’une traduction française.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:25702","title":"Commentaire aux poèmes homériques. Tome II","authors":["Sponde, Jean de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406083191"],"subtitle":"","description":"Publié en 1583 avec une édition des poèmes homériques, le commentaire latin de l'Iliade et de l'Odyssée par Jean de Sponde veut montrer la cohérence et l'intérêt stylistique de l'œuvre d'Homère ainsi que les vertus de ses héros. Il est présenté ici dans une édition moderne et accompagné d’une traduction française.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:25722","title":"Commentaire aux poèmes homériques. Tome III","authors":["Sponde, Jean de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406083207"],"subtitle":"","description":"Publié en 1583 avec une édition des poèmes homériques, le commentaire latin de l'Iliade et de l'Odyssée par Jean de Sponde veut montrer la cohérence et l'intérêt stylistique de l'œuvre d'Homère ainsi que les vertus de ses héros. Il est présenté ici dans une édition moderne et accompagné d’une traduction française.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19557","title":"Contribution à l’étude du paracelsisme en France au xvie siècle (1560-1580) De la naissance du mouvement aux années de la maturité : Le Demosterion de Roch Le Baillif (1578)","authors":["Baudry, Hervé"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455070"],"subtitle":"","description":"Ce volume analyse la place singulière de Roch Le Baillif dans l’histoire du paracelsisme. Il éclaire la genèse historique et intellectuelle ainsi que les enjeux rhétoriques et idéologiques du Demosterion : plus qu’un compendium de médecine, ce traité invite le lecteur à voir en la créature tous les secrets de la nature.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]}]},{"source_id":"garnier:19562","title":"Dante e le origini della cultura letteraria moderna","authors":["Pinto, Raffaele"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459016"],"subtitle":"","description":"​​Quels sont les caractères propres à la culture littéraire moderne ? Croisant les traditions théologiques, philosophiques et scientifiques, ce volume répond à cette question en interrogeant les codes de la production littéraire des deux siècles qui s'écoulent entre Guillaume d'Aquitaine et Dante Alighieri.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:83","title":"De Louis Poirier à Julien Gracq","authors":["Perrin, Dominique"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812440717"],"subtitle":"","description":"Louis Poirier naît en 1910, et donne naissance à Julien Gracq en 1938. De l’arrivée à Paris en 1929 jusqu’à la « drôle de guerre » comprise, une période de troubles et de malaise paroxystique en Europe coïncide dans la biographie de l’écrivain avec le temps de la formation intellectuelle, de l’insertion sociale et de l’invention de soi. Restituer à l’entrée en littérature son contexte historique, en prenant en compte la diversité des témoignages disponibles, permet d’interroger la représentation d’un « classique » souvent réputé « intemporel » ou « insituable ». Mais c’est surtout de trois grands aspects entremêlés de l’énigme Julien Gracq que l’acuité réapparaît. Énigme biographique : Louis Poirier, spécialiste de géomorphologie, militant au Parti communiste, devient à l’âge de vingt-sept ans l’auteur d’emblée paradoxal d’Au Château d’Argol. Énigme épistémologique : le processus de l’écriture est pensé par l’écrivain sur le plan d’une économie affective quasi libidinale. Énigme poétique enfin, l’attention portée au sujet Poirier-Gracq reconduisant au seuil du questionnement sur les textes : comment penser la configuration du sens dans une production romanesque génératrice d’affects aussi complexes ?","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:132538","title":"De manuscrit en bibliothèque Actualité historique et mouvement chez La Boétie","authors":["O’Brien, John"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406160502"],"subtitle":"","description":"Depuis de nouvelles découvertes manuscrites jusqu’aux bibliothèques des collectionneurs, le parcours des études réunies ici interroge l’actualité historique de La Boétie et surtout son Discours de la servitude volontaire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19516","title":"Diane et Actéon Éclats et reflets d’un mythe à la Renaissance et à l’âge baroque","authors":["Casanova-Robin, Hélène"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455179"],"subtitle":"","description":"Cette étude révèle les résonnances dans la littérature et les arts visuels du xvie siècle du mythe de Diane et Actéon tel qu’Ovide l’a fait passer à la postérité. La poétique ovidienne nourrit la rhétorique du furor amoureux, mais aussi une réflexion philosophique et esthétique autour de la figure d’Actéon.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Arts visuels","details":["Iconographie"]}]},{"source_id":"garnier:19681","title":"Discours sur l’occurrence de ses affaires","authors":["Sancy, Nicolas de Harlay, sieur de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457906"],"subtitle":"","description":"Nicolas de Harlay retrace pour la postérité ses années de gloire militaire, diplomatique et politique en rappelant tous les services qu’il rendit à une monarchie ingrate. Ses mémoires offrent une illustration captivante des pouvoirs de l'écriture mémorialiste au moment où s'affirme l'État baroque en France.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Époque moderne","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Époque moderne","details":[]},{"family":"Littérature et études littéraires","subcategory":"Journaux et récits personnels","details":[]}]},{"source_id":"garnier:71904","title":"Dés-admirer Barrès Le prince de la jeunesse et ses contre-lecteurs (1890-1950)","authors":["Dubosson, Fabien"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406072225"],"subtitle":"","description":"Cette étude entend comprendre la réception paradoxale de Barrès à travers des figures comme Léon Blum, André Gide, Albert Thibaudet, Jacques Rivière, André Breton, Louis Aragon ou Joseph Delteil. Il s’agit aussi d’y analyser les différents moments d’une admiration littéraire, de l’exaltation à la « contre-lecture » critique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19877","title":"D’Encre et de poussière L’écriture du pèlerinage à l’épreuve de l’intimité du manuscrit","authors":["Germain-De Franceschi, Anne-Sophie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451805"],"subtitle":"","description":"À côté du succès éditorial des récits de pèlerinage publiés pour un public avide de faire le Grand voyage en esprit, fleurissent des manuscrits s’affranchissant des règles du genre. Cette riche étude propose une réflexion sur la place de la religion chrétienne dans la société en évolution de la Renaissance.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"garnier:19844","title":"D’encre et de sang Simon Goulart et la Saint-Barthélemy","authors":["Huchard, Cécile"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452697"],"subtitle":"","description":"Publié après la Saint-Barthélemy, l'ouvrage militant de Simon Goulart, Memoires de l'estat de France, sous Charles neufiesme, est à la fois une enquête historique, un témoignage et un réquisitoire, une réflexion politique et un discours apologétique. Cette étude envisage l'œuvre de Goulart dans sa totalité et montre comment s'invente une autre manière d'écrire l'histoire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:119684","title":"D’os et de vent Penser la baleine à la Renaissance","authors":["Mangili, Adrien"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406143864"],"subtitle":"","description":"Cette étude cherche à saisir le lent basculement voyant la baleine quitter l’inconnu pour devenir un objet de connaissance et un motif littéraire. Au carrefour d’un renouveau scientifique et d’une instrumentalisation polémique se dessine alors un être polymorphe qui suscite crainte et admiration.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Histoire-Géo","subcategory":"Histoire des sciences et techniques","details":[]}]},{"source_id":"garnier:91982","title":"En lisant, en s’écrivant La drôle de guerre de Jean-Paul Sartre","authors":["Walsh, Francis"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406099086"],"subtitle":"","description":"Arraché à sa vie par la drôle de guerre, Sartre découvre son historicité. Lisant, s’écrivant, il cherchera à se défaire de lui-même en reconfigurant son identité littéraire. Sartre, sujet en situation, apparaît alors comme le mouvement qui tient ensemble le lire et l’écrire, l’identité et l’œuvre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:157883","title":"En lisant, en écrivant Gilles Corrozet, un libraire-auteur au temps de la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406197584"],"subtitle":"","description":"Gilles Corrozet, polygraphe du xvie siècle, nourrit sa pratique d’auteur et de compilateur de sa pratique d’éditeur, et inversement. L’étude de la diversité de son œuvre permet de dessiner ici la figure et la sensibilité d’une personnalité moderne en prise avec le paysage littéraire de son temps.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:87293","title":"Engagements de la forme Une sociolecture des œuvres de Carlo Emilio Gadda et Claude Simon","authors":["Benaglia, Cecilia"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406096931"],"subtitle":"","description":"Cette étude examine la dimension sociopolitique des œuvres des écrivains Carlo Emilio Gadda et Claude Simon et leurs interactions avec les discours idéologiques et les représentations sociales, dans le but de faire émerger le potentiel critique de leurs expérimentations formelles et linguistiques.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:382","title":"Errance et cohérence Essai sur la littérature transfrontalière à la Renaissance","authors":["Usher, Phillip John"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444418"],"subtitle":"","description":"Cet essai étudie une époque où les frontières nationales et continentales, dans les cartes comme dans les esprits, sont loin d'être définies avec exactitude. Il offre moins une histoire abrégée de la littérature géographique de la Renaissance qu'une tentative d'analyser la manière dont les mots articulent les relations entre différents espaces (l'Europe, Jérusalem, le Nouveau Monde). Si les rapports entre ces espaces sont souvent ponctuels, ils participent pourtant pleinement à l'élaboration d'un savoir sur le globe terraqué.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:496","title":"Fac-simile en quadrichromie de l’« Exemplaire de Bordeaux » des Essais de Montaigne Exemplaire contenant le manuscrit de la dernière édition des Essais [exemplaires de tête A-]","authors":["Montaigne, Michel de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444265"],"subtitle":"","description":"Pour la première fois, cette édition reproduit en quadrichromie l'exemplaire dit de Bordeaux des Essais de Montaigne. Cette édition en haute résolution permet, par sa finesse, de suivre les différentes périodes de l'écriture des Essais avec ses reprises immédiates et ses corrections étalées dans le temps que rien, jusqu'à présent, ne permettait de distinguer entre elles. Ce sont donc de nouvelles possibilités de lecture, de recherche et d'analyses sur les Essais que permet cette version inédite.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Récits et essais littéraires","details":["Essais"]}]},{"source_id":"garnier:118507","title":"Faut-il brûler Sagan ?","authors":["Falantin, Flavien"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406143642"],"subtitle":"","description":"Pourquoi l’œuvre de Françoise Sagan a-t-elle pu donner lieu à autant de divisions littéraires et philosophiques ? En décryptant les secrets de fabrication des romans saganiens, cet ouvrage propose une étude non-conformiste du scandale provoqué par l’autrice de Bonjour tristesse.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19577","title":"Flores ætatis novæ Fleurs de la Renaissance Catalogue descriptif des éditions françaises, néo-latines et autres 1501-1600 de la bibliothèque municipale de Versailles","authors":["Peach, Trevor"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459368"],"subtitle":"","description":"Ce catalogue descriptif des éditions françaises, néolatines et autres (1501-1600) de la bibliothèque municipale de Versailles est pourvu de plusieurs index: - index des lieux d'édition et d'impression; - index des noms d'éditeurs et d'imprimeurs; - index des noms de personnes; - index des cotes répertoriées.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19788","title":"Florimond Robertet (?-1527) homme d’état français","authors":["Mayer, Claude-A.","Bentley-Cranch, Dana"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452819"],"subtitle":"","description":"Florimond Robertet était peu connu jusqu'à présent sauf comme mécène aux débuts de la Renaissance française, comme celui qui fit construire le Château de Bury et l'Hôtel d'Alluye à Blois, comme celui qui acquit le tableau de La Vierge au Dévidoir par Leonardo da Vinci et une statue de David en bronze par Michelangelo. En réalité Robertet fut un des hommes politiques des plus importants, sinon le plus important, pendant sa longue carrière sous Charles VIII, Louis XII et François Ier, ce que montre le dépouillement scrupuleux par les auteurs des documents conservés dans, parmi d'autres, les Archives Nationales et le Public Record Office. L'Inventaire de ses papiers, jusqu'ici inédit et qui forme un Appendice de cet ouvrage, établit clairement que ce fut Robertet qui dirigea la politique étrangère française, et cela surtout en 1525 après Pavie quand, pendant la captivité de François Ier, il collabora avec la régente Louise de Savoie à la politique qui libéra le roi et sauva la France.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Biographie","details":["Historique"]}]},{"source_id":"garnier:19502","title":"Fragments sur Montaigne","authors":["Vauvenargues"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455698"],"subtitle":"","description":"Montaigne est la pierre de touche des esprits, au XVIIIe siècle surtout et singulièrement pour le jeune philosophe qui entreprend d'introduire à la connaissance de l'esprit humain. La traversée des Essais fait épreuve et preuve: c'est le moment capital de ce nécessaire dialogue que restitue le manuscrit de Vauvenargues ici reproduit et commenté; dialogue tantôt annoncé, tantôt implicite, où Montaigne apparaît comme modèle, alternativement attractif et répulsif, d'un art complet du penser et de l'écrire. Le moraliste se mesure à cet interlocuteur privilégié comme au représentant parfait de ce qu'il récuse: par opposition à une œuvre fondée sur le défaut de certitude et la conscience cultivée des contradictions internes, il se définit par son besoin de certitude et par une éthique univoque de l'action; en face d'une écriture du dédoublement, du désordre et de l'ironie, il pose l'exigence d'une rhétorique de l'efficacité. L'antagonisme a commencé par la fascination: génie de l'analyse, incomparable expérience du soi. Contre pareil adversaire Vauvenargues doit mobiliser ses principes, se munir d'antidotes: Sénèque, Spinoza, surtout Shaftesbury. Mais il ne cesse, cherchant ailleurs confirmation de ses principes, de répliquer à Montaigne: confrontation exemplaire, qui oblige le moraliste à répondre à l'introspection par l'activité, au style de la méditation par l'éloquence conquérante, par un optimisme vitaliste à l'inquiétante interrogation des Essais.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:85","title":"Genèse de Jean Follain","authors":["Bouygues, Elodie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812440786"],"subtitle":"","description":"Comment lire Jean Follain aujourd’hui ? Son œuvre, qui a longtemps égaré par sa fallacieuse immutabilité, mérite une plus grande attention : poète délicat de la transparence et de la mémoire, Follain est également un humaniste clairvoyant, ainsi que le peintre de l’histoire violente de son temps. L’ouverture des archives au public permet de rétablir son originalité, en particulier au tournant des années trente, au moment où sa révolution silencieuse est rendue inaudible par les trompettes du surréalisme : cisèlement du vers libre, refus de l’image, effacement du sujet lyrique. Le présent ouvrage entend effectuer une « genèse » de Jean Follain en retraçant son itinéraire intellectuel et esthétique à travers diverses formes de sociabilité littéraire ; en montrant quelle place il assigne au poète et à la poésie dans un siècle noir traversé par deux guerres mondiales ; en faisant découvrir son discours théorique inédit ; et enfin en éclairant ses processus de création par un regard sur les manuscrits.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:13166","title":"Giacometti et les écrivains L’atelier sans fin","authors":["Augais, Thomas"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812460500"],"subtitle":"","description":"Giacometti interroge la littérature du xxe siècle à la fois par sa traversée des avant-gardes (revue Documents, surréalisme) et par son retour au modèle extérieur. Croisant les recherches de la phénoménologie, son œuvre ouvre un questionnement radical sur les rapports entre langage et réel.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Arts visuels","details":["Sculpture"]}]},{"source_id":"garnier:95917","title":"Global Montaigne Mélanges en l’honneur de Philippe Desan","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406107996"],"subtitle":"","description":"En hommage au professeur Philippe Desan, ce volume réunit quarante-neuf contributions, consacrées à Montaigne et à son œuvre, en français et en anglais. Dans une perspective transdisciplinaire, elles constituent l’approche la plus complète et la plus novatrice pour la connaissance d’un Montaigne global.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:190","title":"Grammaire du français de la Renaissance Étude morphosyntaxique","authors":["Lardon, Sabine","Thomine, Marie-Claire"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444999"],"subtitle":"","description":"Destinée à ceux qui pratiquent, étudient ou enseignent la langue du xvie siècle, cette grammaire présente quelques-unes des grandes notions morphosyntaxiques du français de la Renaissance. Celles-ci sont replacées dans une perspective historique afin de donner une vision de l'évolution de la langue. Ont été mises à profit les ressources de la base Frantext ainsi que différentes études sur la langue du Moyen Âge, de la Renaissance ou de l'âge classique, en incluant les travaux les plus récents. Sont également rappelées, à chaque fois que leurs analyses diffèrent des nôtres, les positions de plusieurs grammairiens du xvie siècle (Palsgrave, Sylvius, Meigret, R. Estienne et Ramus), dont l'étude est souvent indispensable pour aborder la langue de la Renaissance.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Grammaire et syntaxe"]}]},{"source_id":"garnier:309","title":"Guillaume Budé, philosophe de la culture","authors":["La Garanderie, Marie-Madeleine de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443817"],"subtitle":"","description":"La publication de ce recueil de fragments et d'articles, écrits par Madame Marie-Madeleine de La Garanderie à des dates diverses au cours de quarante années d'études consacrées à l'humanisme parisien et essentiellement à l'œuvre de Guillaume Budé, a pour but d'apporter un complément à sa grande thèse Christianisme et Lettres profanes, à laquelle il fait maintes fois référence.Ce volume constitue une véritable somme des recherches sur Guillaume Budé et son œuvre, encore largement inexplorée.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19865","title":"Histoire, éloquence et poésie à Florence au début du Quattrocento","authors":["Bruni Aretino, Leonardo"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456589"],"subtitle":"","description":"Figure importante du premier humanisme florentin, Leonardo Bruni laissa une œuvre abondante et diversifiée. En offrant des textes caractéristiques de chacune des facettes de la pensée brunienne, cette édition bilingue met en évidence la cohérence d'une œuvre longtemps jugée insaisissable.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Récits et essais littéraires","details":[]}]},{"source_id":"garnier:19507","title":"Inventaire des fonds Montaigne conservés à Bordeaux","authors":["Desgraves, Louis"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456626"],"subtitle":"","description":"Outil précieux pour les études montaignistes, cet inventaire des bibliothèques et archives de Gironde répertorie, avec leurs particularités, plus de 230 éditions des œuvres de Michel de Montaigne, 29 ouvrages de sa bibliothèque, 200 documents originaux et une vingtaine de documents divers et de notes d’érudits.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19480","title":"Itinéraires à Montaigne Jeux de textes","authors":["Garavini, Fausta"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453953"],"subtitle":"","description":"L’éclatante nouveauté des Essais réside dans le renouvellement de l’écriture. Cet ouvrage montre comment l'espace textuel est un espace d'exploration, où s'accomplit la démolition des codes préétablis. La plume de Michel de Montaigne creuse dans le langage les contradictions oblitérées par la pensée systématique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:20490","title":"Jacques Amyot - traducteur des Vies parallèles de Plutarque","authors":["Sturel, René"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812447846"],"subtitle":"","description":"L'étude se divise en deux parties. La première partie (Recherches bio-bibliographiques et critiques) fait le point des manuscrits de dédicace (1542-1546) puis circonscrit le travail d'Aymot entre les manuscrits de dédicace et la première édition (1547-1559) avant d'inventorier les éditions du «Plutarque» d'Aymot (1559-1619). La seconde partie fait l'étude philologique des différents états de la traduction d'Aymot. Elle part du premier état de la traduction dans les manuscrits de dédicace pour étudier ensuite les remaniements de l'édition de 1559 avant de s'arrêter aux «dernières retouches» (1559, 1565, 1583). L'étude se termine par une conclusion, trois appendices, un index des noms propres, un index des mots, locutions et observations grammaticales.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Langues et linguistique","subcategory":"Traduction et interprétation","details":["Traduction"]}]},{"source_id":"garnier:138856","title":"Jean Giono et la Musique","authors":["Parsi, Frédérique"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406173175"],"subtitle":"","description":"Cette étude montre comment la musique, au-delà de sa présence thématique, repérable dès les premiers écrits, outre les fonctions argumentatives, narratives et poétiques qu’elle offre aussi à l’écrivain, s’impose progressivement comme une source d’inspiration et un modèle esthétique pour Jean Giono.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:19651","title":"Journal de voyage en Alsace et en Suisse (1580-1581)","authors":["Montaigne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452536"],"subtitle":"","description":"Les contributions de ce volume sont consacrées au périple alsacien et suisse du Journal de voyage. L’analyse de l’itinéraire du voyageur et du regard de l’écrivain esquissent un voyage humaniste révélateur de la conscience européenne de Michel de Montaigne. Une riche iconographie illustre ces études.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:2429","title":"Journal de voyage Partie en italien","authors":["Montaigne, Michel de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812440984"],"subtitle":"","description":"Le 13 mai 1581, alors qu'il est en cure aux Bains de la Villa, dans le contado de Florence, Montaigne adopte la langue italienne pour rédiger son journal, manifestant une remarquable adaptation culturelle. Cette nouvelle traduction s'est attachée à rendre compte de ce qui au-delà du langage est la trace du sujet Montaigne, pour mettre au jour à quel point le Journal est l'invention de soi.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Journaux et récits personnels","details":[]}]},{"source_id":"garnier:19548","title":"Jésuites, Morisques et Indiens Étude comparative des méthodes d'évangélisation de la Compagnie de Jésus d'après les traités de José de Acosta (1588) et d'Ignacio de las Casas (1605-1607)","authors":["El Alaoui, Youssef"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459528"],"subtitle":"","description":"À partir de traités de José de Acosta et d’Ignacio de las Casas, cette étude montre comment les jésuites se démarquent des autres acteurs de l'évangélisation des Morisques et des Indiens du royaume de Quito par leur vision humaniste de l'Autre et le respect de certains particularismes.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"garnier:19838","title":"La Bibliothèque de Pontus de Tyard Libri qui quidem extant","authors":["Roudaut, François"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454400"],"subtitle":"","description":"Poète, théologien et savant, l'évêque Pontus de Tyard possédait une des plus belles bibliothèques de son temps. Nous permettant d'entrer dans l'atelier du poète de la Pléiade, les livres qui nous sont parvenus dessinent avec précision la carte de la culture d'un lettré de la seconde moitié du xvie siècle.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19878","title":"La Carrière de Montaigne","authors":["Hoffmann, George"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454813"],"subtitle":"","description":"Cette étude de référence restitue l'écriture des Essais dans son contexte historique, social et économique. Renouvelant en profondeur l'image de Michel de Montaigne, elle dépasse le cas particulier pour comprendre comment les hommes de lettres écrivaient et publiaient des livres au xvie siècle.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:63275","title":"La Culture classique d’André Suarès","authors":["Rosny, Antoine de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406079118"],"subtitle":"","description":"Comme poète et dramaturge autant que comme critique, André Suarès (1868-1948) n’a cessé d’exploiter son immense culture classique. Ce volume explore la présence de l’Antiquité dans son œuvre immense et interroge le sens d’une création littéraire très marquée par l’héritage gréco-romain.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19542","title":"La Danse écartelée - de la fin du Moyen Âge à l’Âge classique Mœurs, esthétiques et croyances en Europe romane","authors":["Wéry, Anne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452123"],"subtitle":"","description":"Grâce à un corpus rare et à une approche interdisciplinaire, ce livre apporte un éclairage neuf à l'histoire de la danse et des mentalités européennes à la Renaissance. Novateur, il analyse la polémique morale sur cet art, entre catholiques, protestants et humanistes, enrichissant ainsi la remise en question de nos valeurs.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Danse","Histoire / Société"]}]},{"source_id":"garnier:19881","title":"La Faune brésilienne dans les écrits documentaires du xvie siècle","authors":["Billé, Philippe"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458163"],"subtitle":"","description":"Recensant 400 espèces animales, cet ouvrage analyse le contenu zoologique des principaux documents du XVIe siècle touchant le Brésil et éclaire ainsi le développement de l’histoire naturelle. Il étudie l’attention croissante portée à la culture indigène et son apport au lexique du portugais et du français.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]},{"family":"Histoire-Géo","subcategory":"Histoire des sciences et techniques","details":[]}]},{"source_id":"garnier:20492","title":"La Fille d’alliance de Montaigne - Marie de Gournay","authors":["Schiff, Mario"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812447860"],"subtitle":"","description":"Ce volume s'ouvre par une étude des relations entre Marie de Gournay et Montaigne. L'auteur donne ensuite une édition critique de l'Égalité des Hommes et des femmes (1622) et du Grief des Dames (1626). Cinq appendices complètent ces éditions ainsi qu'un index alphabétique des noms propres.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:19531","title":"La Grammaire du silence - Une lecture de la poésie de Marguerite de Navarre","authors":["Cottrell, Robert D."],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458859"],"subtitle":"","description":"Dans le présent ouvrage, le paradoxe au cœur de la poésie religieuse de Marguerite de Navarre est passé au crible des analyses de l’herméneutique chrétienne, mais aussi des apports des théories psychanalytiques. Le silence y est ainsi conceptualisé comme le langage le plus apte à louer la transcendance divine.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:472","title":"La Littérature au gré du monde Espace et réalité de Cervantes à Camus","authors":["Fougère, Éric"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812440816"],"subtitle":"","description":"L'espace était souvent l'absent du champ littéraire. On le voit désormais pointer dans des productions géopoétiques ou dans des discours géocritiques. Au-delà de l'intérêt mais aussi des limites du mimétique et du tout-textualité, sont lus des espaces écrits d'utopies méconnues du tournant des Lumières ou du premier romantisme aussi bien que d'œuvres moralistes ou romanesques, de récits de voyage ou de vie, de tableaux de mœurs ou de nature, entre le xviie et le xxe siècles.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:19032","title":"La Moïeutique de Cioran L’expansion et la dissolution du moi dans l’écriture","authors":["Stănişor, Mihaela-Genţiana"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406065814"],"subtitle":"","description":"Écrivain bilingue, Cioran a conçu deux œuvres distinctes qui expriment différemment les deux visages de son existence et ses deux patries. Il a mis en relief deux topoï : la Roumanie – lieu de désastre – et la France – espace d’altérité. Il a esquissé la portraiture de l’être, libéré aussi bien qu’entravé par le mot.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:6390","title":"La Muse et le Compas : - poétiques à l’aube de l’âge moderne Anthologie","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812434617"],"subtitle":"","description":"Cet ouvrage réunit trois arts de poésie française écrits vers la fin du xve siècle, l'Instructif de seconde rhétorique, l'Art de rhétorique de Molinet et un Traité de rhétorique. Ces ouvrages dressent un état des lieux du savoir poétique dont bénéficiaient les poètes de la première Renaissance et leurs lecteurs.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:4","title":"La Philosophie de la lumière chez Dante Du Convivio à la Divine comédie","authors":["Ottaviani, Didier"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453403"],"subtitle":"","description":"L’étude de la thématique de la lumière du Convivio à la Divine comédie permet de mettre en évidence la manière dont Dante parvient à harmoniser les différentes traditions philosophiques qui le précèdent. Ce faisant, il propose une philosophie nouvelle qui clôt une époque et ouvre sur la Renaissance.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19699","title":"La Place du Prince Perspective et pouvoir dans le théâtre de cour des Médicis, Florence (1539-1600)","authors":["Marciak, Dorothée"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453342"],"subtitle":"","description":"L'adaptation de la perspective picturale au théâtre de cour des Médicis au xvie siècle consacre le dispositif de représentation illusionniste comme instrumentum regni. La « place du prince » offre une image opérante de la puissance souveraine que la pensée politique post-tridentine identifiera comme l’œil de Dieu.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Histoire / Société"]}]},{"source_id":"garnier:100325","title":"La Prudence d’après Michel de Montaigne et Baltasar Gracián Entre le ciel et la terre","authors":["Aponte-Olivieri, Sara"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406113744"],"subtitle":"","description":"Figures emblématiques de la première modernité, Michel de Montaigne et Baltasar Gracián élaborent des représentations de la vertu de prudence porteuses de résonances théologiques. Le présent ouvrage compare les convergences du prudentiel et du providentiel dans leurs écrits.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19874","title":"La Réception de Rabelais en Europe du xvie au xviiie siècle","authors":["De Grève, Marcel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457012"],"subtitle":"","description":"Les études de Marcel De Grève ont marqué un tournant capital dans la critique de la réception rabelaisienne. Ce volume, réunissant des articles publiés entre 1953 et 1998, met l’accent sur l’étonnante vitalité d’une œuvre constamment renouvelée et enrichie par ses lecteurs, imitateurs et interprètes.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19545","title":"La Réception d’Agrippa d’Aubigné - (xvie-xxe siècles) Contribution à l’étude du mythe personnel","authors":["Schrenck, Gilbert"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455018"],"subtitle":"","description":"Si Agrippa d’Aubigné a élaboré au sein de son œuvre l’image du soldat-poète qu’il voulait laisser à la postérité, sa consécration reste tardive. De la figure exécrée du partisan protestant à l’image du marginal révolté exaltée par les romantiques, cet ouvrage retrace le singulier cheminement du mythe albinéen.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:98833","title":"La Science prise aux mots Enquête sur le lexique scientifique de la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406109976"],"subtitle":"","description":"Interroger le lexique scientifique par ses termes les plus usuels comme curiosité, observation ou expérience, tant en médecine, zoologie que géographie, permet d’ouvrir une réflexion de fond sur la conception des savoirs à la Renaissance, en prenant au mot la science telle qu’elle s’écrit.","from":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Lexicologie et lexicographie"]}]},{"source_id":"garnier:19669","title":"La Traduction des Psaumes de David par Clément Marot Aspects poétiques et théologiques","authors":["Reuben, Catherine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452932"],"subtitle":"","description":"Qu'est-ce qui explique le succès remarquable de la traduction des Psaumes de David par Clément Marot? Sa poésie laïque annonce le succès de cette traduction religieuse dont les formes métriques sont basées sur ses Chansons, déjà si populaires. La traduction arrive à un moment propice dans l'histoire de la Réforme et permet à la congrégation de participer pleinement aux offices de l'église. Marrot se révèle ainsi non seulement comme le premier poète français de la Renaissance, mais aussi comme un poète important de la Réforme, qui a donné une voix aux évangéliques. Les six chapitres de ce livre traitent des éditions et des sources de la traduction des psaumes, leur forme métrique et la manière dont Marot reflète le parallélisme, la répétition et les images qui font partie intégrante du texte original hébraïque. Il est question d'une critique des Psaumes de Marot tant du point de vue poétique que théologique. Catherine Reuben s'adresse dans ce livre aux amateurs du poète Marot qui admirent sa poésie laïque, et ceux et celles pour qui sa traduction des psaumes est la traduction par excellence du psautier de la première moitié du seizième siècle. Il intéressera les théologiens aussi bien que les étudiants de la Réforme, les spécialistes littéraires et tous ceux qui aiment la poésie de Marot.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19748","title":"La Voix de la nature - dans l’œuvre de Jacques Peletier du Mans (1517-1582)","authors":["Arnaud-Seigle, Sophie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459030"],"subtitle":"","description":"L’œuvre riche et variée de Jacques Peletier du Mans trouve son unité et sa cohérence dans la figure de la nature, miroir de la puissance et de la bonté de Dieu. Cet ouvrage analyse son incessante quête du sens de la nature, puis celle d’une parole naturelle délivrant l'écho de l'harmonie physique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:78777","title":"La « Philautie » humaniste, héritages et postérité","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406088370"],"subtitle":"","description":"Les études réunies dans cet ouvrage s’attachent à déterminer les significations exactes que recouvre la notion de philautie, essentielle dans la création littéraire et la réflexion philosophique des xvie et xviie siècles, les héritages dont elle procède, les modalités selon lesquelles elle s’impose en ce temps.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:491","title":"La « Pléiade » de Saint-John Perse La Poésie contre l’Histoire","authors":["Ventresque, Renée"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444951"],"subtitle":"","description":"Réalisé par Saint-John Perse, le volume de ses Œuvres complètes dans la «Pléiade» efface les frontières entre poésie et politique, histoire et fiction, édition et écriture. Les personnalités historiques rencontrées par Alexis Leger y deviennent, comme le diplomate-poète lui-même, des personnages de l'œuvre poétique de Saint-John Perse. L'autoportrait intellectuel, littéraire et politique qui s'y inscrit, y acquiert une cohérence qui n'existe que dans l'imaginaire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:3739","title":"Lagarce Un théâtre entre présence et absence","authors":["Parisse, Lydie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812413971"],"subtitle":"","description":"Cet ouvrage constitue une lecture singulière du théâtre de Lagarce, qui pose la question de nos représentations et de la représentation théâtrale. C’est sous l’angle de la philosophie et de la littérature que cette étude aborde successivement la parole trouée de l’auteur et la mythologie de la figure auctoriale.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:98829","title":"Le Centre de gravité À propos des écrits de Louis-René des Forêts","authors":["Roudaut, Jean"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406115717"],"subtitle":"","description":"Dans cette étude sur Louis-René des Forêts, il s’agit moins de reprendre ce qui a pu être dit sur la vanité du langage que de s’attacher à comprendre ce que peut signifier la pensée que le langage possède « des propriétés sonores d’une étendue insoupçonnée ».","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19711","title":"Le commentaire de Marsille Ficin, Florentin : sur le Banquet d'amour de Platon","authors":["Silvius, Symon"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459252"],"subtitle":"","description":"Parue en 1546, la première traduction intégrale en français du Commentaire sur le Banquet de Platon de Marsille Ficin révèle un remarquable traducteur : Symon Silvius, valet de chambre de Marguerite de Navarre. Cette édition critique en éclaire les enjeux philologiques, linguistiques et historiques.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19471","title":"Le dernier Montaigne","authors":["Nakam, Géralde"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454905"],"subtitle":"","description":"Le Dernier Montaigne: le titre indique un parcours, et la fin de ce parcours. Si forte est, en effet, l'unité des Essais, qu'on risque d'oublier combien, d'édition en édition, ils changent. Mais l'oublier, c'est trahir cette unité même et la «vie» du texte dans ses «métamorphoses». Montaigne, en se regardant dans un miroir ou dans l'un de ses portraits, constate: «combien de fois ce n'est plus moi!» C'est toujours lui, mais un autre. Cette «fois-là», en fin de parcours, quel est-il? Un autre? En tout cas, le dernier. Montaigne parle et se montre dans son livre dans la dernière de leurs communes «mutations». Les Essais de 1588 étaient tout autres que ceux de 1580, en profondeur et, par l'adjonction d'un livre entier, ostensiblement. Le texte de 1592, à la mort de l'auteur, est tout autre encore. Les ajouts de sa «dernière main» déroulent un texte autre, continu, soit qu'ils s'adjoignent au précédent, ou circulent à travers lui, en drainant des apports autres de l'histoire de la France, de celle de Montaigne, de celle de son livre, d'une vérité généralement plus dramatique, plus tendue. Ces apports modifient le texte antérieur, là même où il reste inchangé depuis 1588, depuis 1580. Car «l'essai» de Montaigne est un organisme vivant. La mort seule y met son point final et achève, sans l'achever, le puzzle entier du livre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:3081","title":"Le Gala des incomparables Invention et résistance chez Olivier Cadiot et Nathalie Quintane","authors":["Farah, Alain"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812409561"],"subtitle":"","description":"Olivier Cadiot et Nathalie Quintane incarnent, malgré la prétendue mort des avant-gardes, la poursuite de l'invention littéraire. Les tensions qu'ils ravivent entre littérature et monde contemporains produisent une joie qui impose à l'apathie actuelle une autre radicalité esthétique et politique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19643","title":"Le lecteur, l’auteur et l’écrivain - Montaigne 1492-1592-1992","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455339"],"subtitle":"","description":"","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19528","title":"Le Livre au xvie siècle Éléments de bibliologie matérielle et d’histoire","authors":["Roudaut, François"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454325"],"subtitle":"","description":"Ce livre entend être une rapide introduction à la connaissance du livre imprimé au xvie siècle, sous les trois sujets suivants : la fabrication, la vente et la lecture. Un des buts est de montrer que les conditions matérielles contribuent à influer sur les orientations intellectuelles.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:136374","title":"Le Monde sous l’œil des médecins Nature et politique à l'Escorial et au Vatican (xvie siècle)","authors":["Andretta, Elisa"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406165163"],"subtitle":"","description":"Centré sur l’Escorial et le Vatican, le livre explore le rôle politique et culturel essentiel des médecins du xvie siècle. Impliqués dans l’aménagement de jardins, bibliothèques et collections, ils contribuent à façonner de nouvelles pratiques d’'interprétation et de gouvernement du monde.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]}]},{"source_id":"garnier:19535","title":"Le Platonisme de Marsile Ficin et la Cour d’Urbin","authors":["Pernis, Maria Grazia"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457333"],"subtitle":"","description":"Cette étude d’ensemble analyse l’influence de la philosophie néo-platonicienne qui s'exerça à la cour d’Urbin dans le domaine des lettres, de l'architecture et de la peinture. Sont ici examinés les relations entre le cercle de Marsile Ficin et la cour d'Urbin ainsi que le programme architectural du palais ducal.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19527","title":"Le Poète architecte en France Constructions d’un imaginaire monarchique","authors":["Skenazi, Cynthia"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452970"],"subtitle":"","description":"Des arts visuels à la poésie, de la politique à l'esthétique, ce volume étudie la construction d’un imaginaire monarchique dans l’œuvre des poètes et les édifices royaux. Si elle sert la propagande nationaliste et use de stratégies de persuasion, l’alliance des arts nourrit aussi l'imagination créatrice de formes.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Architecture","details":["Histoire / Patrimoine"]}]},{"source_id":"garnier:86729","title":"Le Profane et le Sacré dans l’Europe latine ve-xvie siècles","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406091486"],"subtitle":"","description":"Les articles de cet ouvrage étudient la rencontre du sacré et du profane chez des auteurs médio et néolatins, dans des œuvres de circonstance, des poésies religieuses, ou encore des traités politiques ou pédagogiques, de l’Antiquité tardive au milieu du xvie siècle.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]}]},{"source_id":"garnier:19478","title":"Le Promenoir de Monsieur de Montaigne","authors":["Gournay, Marie de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457036"],"subtitle":"","description":"Marquant l'entrée en littérature de la première éditrice des Essais, cette histoire tragique illustre la progressive affirmation de sa qualité d'auteur dans un texte fondateur constamment renouvelé. La présente édition permet d'apprécier la part de stratégie littéraire entrant dans la construction de ce récit.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Fiction","details":["Nouvelles"]}]},{"source_id":"garnier:352","title":"Le Socratisme de Montaigne","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812445125"],"subtitle":"","description":"Ce recueil d'études interroge l'intérêt manifesté par Montaigne vis-à-vis de Socrate. Il s'agit de dessiner les contours de la figure de Socrate telle qu'il la perçoit, de dégager ce qu'il relève, voire reprend de la démarche socratique et de voir comment la vie de Socrate influence sa propre conception de la philosophie. Avec Montaigne s'affirme une vision moderne de Socrate, moins métaphysique, moins exemplaire et plus purement humaine, qui est encore largement la nôtre aujourd'hui.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:88493","title":"Le Théâtre panique de Fernando Arrabal « Science de l’essence de la confusion »","authors":["Combes, Émilie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406095897"],"subtitle":"","description":"L’exploration des principaux piliers de l’esthétique panique permet de comprendre comment se révèle la tension entre abject et sublime dans le théâtre de Fernando Arrabal, et de voir que l’espoir et la quête de soi l’éloignent d’une forme de tragique, pour devenir un moyen d’accéder à la connaissance de soi.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19630","title":"Le Visage changeant de Montaigne - The Changing Face of Montaigne","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456480"],"subtitle":"","description":"Ce volume reflète les visages changeants de Michel Montaigne aussi bien que la variété herméneutique qu’apporte la critique pour aborder un sujet aussi « ondoyant ». Sont convoquées plusieurs disciplines, des études classiques à l'anthropologie, l'iconographie, le droit, la sémiotique et la psychanalyse.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:136","title":"Les Audaces de la prudence Littérature et politique aux xvie et xviie siècles","authors":["Goyet, Francis"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812441127"],"subtitle":"","description":"Le propos de ce livre est de demander à la pensée ancienne de la prudentia une théorie complète de la décision. La particularité de cette pensée était de ne pas séparer décision et jugement, les deux se disant en latin judicium. Son enjeu était de devenir un excellent « juge ». On apprenait à prendre des décisions en jugeant après coup celle des autres. La prise de décision était un saint des saints où entrer par un lent processus, un cheminement, avec sa rationalité mais aussi sa part mystérieuse de liberté. Le tout initiera à cet autre mystère qu'est la lecture critique, la seule digne d'un juge et d'une krisis.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:16783","title":"Les Carabiniers, de Joppolo à Audiberti, Rossellini, Godard Génétique d’une prise d’armes","authors":["Resche, Stéphane"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406068846"],"subtitle":"","description":"La pièce I carabinieri constitue le faire-valoir indiscuté de l’œuvre théâtrale de B. Joppolo (1906-1963). Cette étude génétique compare les différentes versions de cette satire de la guerre, du manuscrit originel (1945), aux apports d'Audiberti (1954), de Rossellini (1962) et de Godard (1963).","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:12170","title":"Les Controverses des Sexes Masculin et Femenin","authors":["Pont, Gratien du"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406057352"],"subtitle":"","description":"Cette édition critique des Controverses des Sexes Masculin et Femenin reconsidère la position de l’ouvrage dans la Querelle des femmes, met à jour son inventio par une étude des sources et définit la poétique de l’ouvrage, fondée sur le recours à des rimes et à des formes fixes complexes.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:19491","title":"Les Essais de Montaigne Méthode(s) et méthodologies","authors":["Supple, James J."],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456220"],"subtitle":"","description":"La critique montaigniste est tout aussi riche qu’elle est divisée. Le présent ouvrage entreprend de démontrer que ce « tintamarre de cervelles [critiques] » est le résultat d'une écriture sans « paroles de liaison » qui attribue au lecteur la responsabilité de déterminer la nature de sa démarche philosophique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19515","title":"Les Essais de Montaigne, miroir et procès de leur temps Témoignage historique et création littéraire","authors":["Nakam, Géralde"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454899"],"subtitle":"","description":"Une œuvre vit dans son temps, de son temps. Tous les événements du siècle bouleversé de Montaigne contribuent à nourrir et à façonner son livre. L'essayiste observe, compare, juge, agit. La tour où il écrit n'a rien d'une tour d'ivoire. «J'étudie tout, ce qu'il me faut fuir, ce qu'il me faut suivre», précise-t-il. Le monde contemporain est le champ principal de son expérimentation humaine, dans laquelle il se montre ethnologue, anthropologue, et homme politique. Dans cette œuvre singulière des Essais, qui n'est ni Histoire ni récit, ni discours, qui ne se rattache à aucune forme connue de la littérature, où s'invente l'intériorité, et qui, tout à la fois répond à son temps, quelles sont les réponses de Montaigne? Dans le «miroir» des faits et des idées contemporains, à la lumière de sa culture, il découvre sa «disconvenance», et du «procès» qu'il dresse des structures et des mentalités d'un «temps malade», émerge et se précise son autoportrait. La présente étude s'offre dans une perspective comparative et selon un relief fait de plans successifs. A propos de chacune des questions abordées (l'argent, la société, la royauté, la torture, le Nouveau Monde, etc.), on lira donc, après une brève mise au point historique, des réponses contemporaines, d'abord, puis celle de Montaigne, dans sa «forme», dans son langage propres.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19883","title":"Les Femmes et l’histoire familiale (xvie - xviie siècle) Renée Burlamacchi Descrittione della Vita del Sig Michele Burlamachi (1623) Jeanne du Laurens Genealoie de Messieurs du Laurens (1631)","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459092"],"subtitle":"","description":"Réunissant les écrits de Renée Burlamacchi et de Jeanne du Laurens, cet ouvrage propose de rares images de la vie familiale et une perspective personnelle sur l'expérience féminine pendant les troubles civils et religieux de la seconde moitié du xvie siècle. L’introduction présente la vie de ces mémorialistes.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Biographie","details":["Historique"]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Biographie","details":["Historique"]},{"family":"Littérature et études littéraires","subcategory":"Journaux et récits personnels","details":[]}]},{"source_id":"garnier:19524","title":"Les Géants de Rabelais - Folklore, histoire ancienne, nationalisme","authors":["Stephens, Walter"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459429"],"subtitle":"","description":"Les Géants de Rabelais, érudits et chrétiens, jouent un rôle crucial dans l’évolution de la figure du géant depuis l’Ancien Testament. Les fictions rabelaisiennes naissent de l’opposition entre les géants malveillants de la tradition folklorique et les géants héroïques d’une nouvelle histoire nationale.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19564","title":"Les Idées stoïciennes dans la littérature morale des xvie et xviie siècles (1575-1642)","authors":["Carabin, Denise"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453144"],"subtitle":"","description":"Espérant répondre aux attentes d'une époque troublée, l’Europe humaniste redécouvre le stoïcisme. Cette sagesse antique propose des solutions, mais suscite aussi des controverses. Cette histoire du néo-stoïcisme éclaire les transformations idéologiques et littéraires opérées au tournant des xvie et xviie siècles.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19742","title":"Les Images ou Tableaux de platte-peinture. Tomes I-II Traduction et commentaire de Blaise de Vigenère (1578)","authors":["Philostrate"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458378"],"subtitle":"","description":"","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Récits et essais littéraires","details":[]},{"family":"Art / Culture","subcategory":"Arts visuels","details":["Iconographie"]}]},{"source_id":"garnier:3087","title":"Les Interférences des écoles de pensée antiques - dans la littérature de la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812410338"],"subtitle":"","description":"Les études réunies ici cernent le rôle du syncrétisme philosophique dans l'invention du « sujet » littéraire ainsi que l'effet en retour de l'optique « littéraire » sur notre appréhension des discours philosophiques. Elles situent ces contaminations et transformations comme le propre des textes renaissants.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:102439","title":"Les Interstices de la conversation - dans les romans de Proust et de Sarraute","authors":["Montier, Solenne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406114772"],"subtitle":"","description":"Les interstices de la conversation révèlent une filiation reliant Marcel Proust et Nathalie Sarraute. Ces bribes fictionnelles commentent ou diffractent l’interaction en cours, pour privilégier ses résonances imaginaires. Elles éclairent les termes de l’intersubjectivité au cœur du projet des deux auteurs.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19818","title":"Les Jeux de l’échange Entrées solennelles et divertissements du xve au xviie siècle","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457630"],"subtitle":"","description":"Cet ouvrage collectif aborde l’échange dans les liens rituels, politiques, économiques ou symboliques. Inscrit dans les études littéraires et les sciences humaines, il étudie les fêtes et les divertissements, ces manifestations culturelles qui interrompent la quotidienneté.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Histoire / Société"]}]},{"source_id":"garnier:1003","title":"Les Lettres et la Tiare E. S. Piccolomini, un humaniste au xve siècle","authors":["Stolf, Serge"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812445071"],"subtitle":"","description":"Enea Silvio Piccolomini (1405-1464), grand représentant de l’humanisme du xve siècle, fut lettré, diplomate, prélat, pontife sous le nom de Pie II. Homme de plume, d’action et de convictions, il aborda les questions cruciales qui se posaient à son temps, dans une œuvre littéraire considérable où il instaure un dialogue fécond entre culture séculière et culture chrétienne, identifiant l’Europe à la civilisation des lettres humaines et des valeurs spirituelles.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19835","title":"Les Liens à renouer Scepticisme, possibilité, imagination politique chez Montaigne","authors":["Panichi, Nicola"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457845"],"subtitle":"","description":"Réfléchir sur la phénoménologie des liens est la façon qu’a Montaigne d'exorciser le scepticisme intégral. Il transforme le scepticisme traditionnel dans la perspective de l’être comme discours, de la possibilité et du pluralisme. La recherche reconstitue la genèse et les effets de ce parcours.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:3370","title":"Les Mailles du filet - ou Le Temps immobile de Claude Mauriac","authors":["Thoizet, Évelyne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812413766"],"subtitle":"","description":"À partir de son journal intime, Claude Mauriac compose une œuvre monumentale, Le Temps immobile, dont les mailles retiennent ou laissent couler le temps, résolvant ainsi certains problèmes temporels ou faisant apparaître de nouvelles apories, à la croisée de la littérature et de la philosophie.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19584","title":"Les Miroirs du paon Rites et rhétoriques politiques dans la France de l’Ancien Régime","authors":["Lardellier, Pascal"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458453"],"subtitle":"","description":"Les entrées royales connurent leur âge d'or à la Renaissance, tandis que l'absolutisme monarchique se consolidait. Les approches historiques, anthropologiques, politiques, stylistiques et médiatiques se complètent ici pour étudier la spectacularisation du politique à l’œuvre dans ce grand cérémonial d'État.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Histoire-Géo","subcategory":"Histoire culturelle et sociale","details":[]}]},{"source_id":"garnier:19572","title":"Les Méditations chrétiennes d’un parlementaire Étude sur les premières œuvres de piété de Guillaume Du Vair","authors":["Petey-Girard, Bruno"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452260"],"subtitle":"","description":"Guillaume Du Vair transforme le genre de la méditation biblique en écrivant en laïc et en homme de culture capable d'aborder les questions spirituelles sans controverse. Cette étude replace ses premières œuvres de piété dans leur contexte historico-politique, religieux, spirituel et rhétorique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19802","title":"Les Métamorphoses d’Hermès Tradition alchimique et esthétique littéraire dans la France de l’âge baroque (1583-1646)","authors":["Greiner, Frank"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453991"],"subtitle":"","description":"À la fin du xvie et au début du xviie siècle, la promotion et la diffusion de la science alchimique se conjuguèrent avec l'élaboration d’une esthétique du mystère marquant de son empreinte caractéristique un vaste corpus de traités, de discours et de commentaires, mais aussi de textes littéraires.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Ésotérisme"]}]},{"source_id":"garnier:3554","title":"Les Poètes modernes - et le cinéma (1910-1930)","authors":["Cohen, Nadja"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812417757"],"subtitle":"","description":"Art machinique de l’image-mouvement, le cinéma intéresse des poètes novateurs comme Apollinaire et les surréalistes et constitue une mutation anthropologique qui pèse sur le devenir de la poésie. Cet ouvrage analyse les liens entre poètes et cinéma en étudiant des textes méconnus aux frontières entre les arts.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]}]},{"source_id":"garnier:19510","title":"Les Repentirs de l’Exemplaire de Bordeaux - (Montaigne, Essais, Livre I)","authors":["Iemma, Paola"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458415"],"subtitle":"","description":"« J’ajoute mais je ne corrige pas », écrivait Montaigne. Paola Iemma interroge dans cet ouvrage les variantes de l’exemplaire de Bordeaux à la lumière de la réflexion métascripturale qui parcourt les Essais.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:1010","title":"Les Romans de Bernanos Métamorphoses de la transcendance","authors":["Robinot-Serveau, Karine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812442421"],"subtitle":"","description":"Confronter narration et transcendance à partir des métamorphoses que Bernanos fait subir à ses romans exige une triple approche. L’étude générique montre que les huit narrations relèvent le défi d’intégrer une notion théologique, métaphysique et mystique. L’analyse génétique dessine les métamorphoses topographiques et chronographiques. La quête herméneutique révèle deux supports privilégiés : la Bible comme transcendance textuelle et l’aventure mystique chrétienne comme transcendance faite chair.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19506","title":"Les Sources de la pensée philosophique de Raimond Sebond (Ramon Sibiuda)","authors":["De Puig Oliver, Jaume"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455704"],"subtitle":"","description":"L’œuvre de Raimond Sebond est ici envisagée dans son ensemble, des sources aux spécificités de sa pensée philosophique. Le portrait intellectuel qui s’en dégage est celui d’un auteur érudit mais indépendant des écoles de son temps, d’un penseur à la fois théologien, philosophe humaniste et apologiste de la foi.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19508","title":"Les Terrains vagues des Essais : - Itinéraires et intertextes","authors":["McKinley, Mary B."],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457234"],"subtitle":"","description":"Les métaphores spatiales dessinent un paysage de l'esprit montaignien, tout en mettant en scène l'itinéraire de l'écrivain dans son parcours d'imitatio. C'est ainsi qu'il prend dans les livres de ses prédécesseurs une \"route par ailleurs\" pour créer dans les Essais une poétique du récit vagabond.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19534","title":"Les Théories de la Dispositio et le grand œuvre de Ronsard","authors":["Jomphe, Claudine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452710"],"subtitle":"","description":"La structure de la Franciade est présentée comme l’une des causes de son échec à rivaliser avec ses modèles antiques. Mais les particularités de la dispositio de cette épopée donnent au poème sa couleur caractéristique, tout en révélant les conceptions ronsardiennes de l'héroïsme, de la vertu et du plus haut sens.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19869","title":"Les Voyages aux Indes orientales Contenans une description exacte de l'Indostan, des nouveaux Mogols, et des autres peuples et païs des Indes orientales, avec leurs mœurs et maximes, religions, fêtes, temples, pagodes, cimetiéres, commerce, et autres choses remarquables","authors":["Thévenot, Jean de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456367"],"subtitle":"","description":"À la différence des autres voyageurs de son temps, Jean de Thévenot, dont nous présentons ici le récit de son voyage en Inde, est surtout curieux de géographie et de sciences naturelles. L'intérêt de ce texte réside dans son honnêteté, la richesse de sa documentation et la profondeur de ses analyses.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]},{"family":"Art / Culture","subcategory":"Voyage","details":["Asie / Moyen-Orient"]}]},{"source_id":"garnier:344","title":"Les Voyageurs d’îles - sur la route des Indes aux xviie et xviiie siècles","authors":["Girault-Fruet, Arlette"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812439223"],"subtitle":"","description":"Dans leurs relations, les premiers voyageurs des Mascareignes, en réinvestissant les mêmes topoï, chargent la réalité référentielle de significations culturelles : pour le lecteur, il n'y a finalement pas d'îles inconnues, seulement des îles perdues que la lecture permet de retrouver, et qui restent toujours surprenantes sans être tout à fait nouvelles. Narrateur et lecteur se découvrent donc, en toute connivence, Voyageurs d'îles, les îles étant en somme « des rêves qui ont jeté l'ancre ».","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:19756","title":"Lettres et poèmes Édition critique, introduction et commentaire du ms. 1134 de la Bibliothèque de l'Université de Paris","authors":["Bovelles, Charles de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452598"],"subtitle":"","description":"Cette édition critique permet de découvrir un manuscrit qui n'était pas destiné à la publication. Elle révèle de nouvelles facettes de l’un des plus remarquables penseurs français du XVe siècle. Le style tranche ici avec celui des traités : le chanoine se montre tantôt mystique, tantôt acerbe, mais aussi badin.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Correspondance","details":[]}]},{"source_id":"garnier:3280","title":"Libertin ! Usage d’une invective aux xvie et xviie siècles","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812410390"],"subtitle":"","description":"Ce livre étudie de manière transversale les multiples usages attestés du terme « libertin » chez les auteurs du début de l'époque moderne, rendant ainsi manifeste la diversité des emplois et déplacements d'une invective, qu'il s'agisse de stigmatiser, de s'en revendiquer, ou de s'en protéger.","from":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Lexicologie et lexicographie","Discours et pragmatique"]}]},{"source_id":"garnier:19882","title":"Ligne de foi La Compagnie de Jésus et l’esclavage dans le processus de formation de la société coloniale en Amérique portugaise (xvie-xviie siècles)","authors":["Zeron, Carlos Alberto de Moura Ribeiro"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453038"],"subtitle":"","description":"Le Brésil des xvie et début xviie siècles fut le laboratoire d’une société coloniale fondée essentiellement sur l’esclavage. L’ouvrage étudie le rôle que joua dans cette élaboration la Compagnie de Jésus, qui en fut l’un des acteurs fondamentaux.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Époque moderne","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"garnier:19784","title":"Lire les Essais de Montaigne","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456244"],"subtitle":"","description":"Poursuivant le débat amorcé par Jean-Yves Pouilloux dans Lire les Essais de Montaigne, ces contributions adoptent des approches variées pour interroger les jeux complexes de l’intertextualité, l’évolution de l’interprétation du texte au fil des rééditions, mais aussi le rôle et la place dévolus au lecteur.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:3332","title":"Lire Les Tragiques d’Agrippa d’Aubigné","authors":["Lestringant, Frank","Monferran, Jean-Charles"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812417603"],"subtitle":"","description":"Cet ouvrage constitue une introduction aux Tragiques d’Agrippa d’Aubigné et aux sept livres qui conduisent de Misères à Jugement. Il invite à pénétrer au cœur de la Divine Comédie huguenote et inscrit l’œuvre dans son contexte historique, politique et esthétique, tout en dégageant son irréductible originalité.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:13363","title":"Louis de Gonzague Frick dans tous ses états Poète, soldat, courriériste, ami","authors":["Steele, Stephen","Bourreau-Steele, Anne-Françoise"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406058236"],"subtitle":"","description":"« Directeur du moral des écrivains mobilisés » de 1914-1918 selon Thibaudet, Louis de Gonzague Frick, au nom contesté et à la poésie reléguée, est l’élégant des petites revues et de la vie littéraire parisienne, de La Phalange de Royère jusqu’à la Seconde Guerre mondiale, quand son activité diminue.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19556","title":"Louise Labé Lyonnaise - ou la Renaissance au féminin","authors":["Rigolot, François"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454462"],"subtitle":"","description":"Au fil de cette étude se tisse une image de Louise Labé plus complexe que celle livrée par la tradition. Invitée par son entourage humaniste lyonnais à retrouver la voix de Sappho et à en procurer une à Laure, la Belle Cordière s’inscrit dans la tradition antique tout en créant un idéal nouveau.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19606","title":"Lucain et la littérature de l’âge baroque en France Citation, imitation et création","authors":["Ternaux, Jean-Claude"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456428"],"subtitle":"","description":"La Pharsale est probablement l’œuvre latine la plus en adéquation avec l'âge baroque. Cet ouvrage analyse l’influence exercée par l’épopée de Lucain dans les années 1550-1660. Ses métamorphoses génériques et sa langue qui frappe vivement l’esprit inspirèrent les écrivains d’Agrippa d'Aubigné à Pierre Corneille.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19782","title":"Lucien de Samosate et la Renaissance française","authors":["Mayer, Claude-A."],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452796"],"subtitle":"","description":"Dans cet ouvrage, C.-A Mayer analyse tout d'abord la «méthode» de Lucien avant de relever son influence indirecte dans les traductions poétiques et les œuvres non satiriques de la Renaissance. Il étudie ensuite les influences directes de Lucien dans les «premières» imitations, puis dans Rabelais, Bonaventure des Périers et Jaques Tahureau. Le dernier chapitre est consacré à la satire antiaulique, des débuts jusqu'à L'Amye de Court, puis dans Le Philosophe de Court, Le Poète Courtisan et Le Medecin Courtizan.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:383","title":"L’Acte éditorial Publier à la Renaissance et aujourd’hui","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812439711"],"subtitle":"","description":"Peut-on parler de filiation entre la publication artisanale d'ouvrages de la Renaissance et la pensée du livre dans l'édition contemporaine ? Aux deux époques considérées, les instances et intentions, les modalités et responsabilités de l'acte éditorial et ses finalités permettent de l'affirmer. Il apparaît ainsi comme un geste, théorique et critique, de lecture, d'interprétation et d'accomplissement de l'œuvre littéraire. Une étude croisant Théorie littéraire et Histoire du livre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:19566","title":"L’Alchimie à la Cour de Côme Ier de Médicis : - savoirs, culture et politique","authors":["Perifano, Alfredo"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451928"],"subtitle":"","description":"Côme Ier sait mettre, avec génie, la culture et la science au service de la politique. Les expériences alchimiques qu’il commandite façonnent l’image d’un prince médecin et philosophe. Cet ouvrage est une contribution significative à l’histoire de la politique culturelle et de l'emblématique des Médicis.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Histoire des sciences et techniques","details":[]}]},{"source_id":"garnier:329","title":"L’Archive du Coup de dés Étude critique de la réception d’Un coup de dés jamais n’abolira le hasard de Stéphane Mallarmé (1897-2007)","authors":["Roger, Thierry"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812445187"],"subtitle":"","description":"Ce livre, qui entend rompre avec une vision trop intuitive de l'effet du Coup de dés au xxe siècle, et faire la généalogie d'une doxa créditant le poème mallarméen d'une descendance foisonnante, reconstitue les étapes d'une réception tant « en discours » (conditions de lisibilité), qu'« en actes » (transpositions extra-littéraires). Cette archive du Coup de dés débouche alors sur l'archéologie d'une certaine tradition moderne, saisie à travers les manifestations de la productivité d'une œuvre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19661","title":"L’Art de la peinture Peinture et théorie à Séville au temps de Francisco Pacheco (1564-1644)","authors":["Fallay d'Este, Lauriane"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456640"],"subtitle":"","description":"Cette étude du milieu artistique sévillan analyse comment ont été acculturées les théories et formes esthétiques nouvelles venues d’Italie, de la fin du xvie siècle à 1640. Peintre, théoricien et poète humaniste, Francisco Pacheco, maître et beau-père de Diego Vélasquez, joue un rôle majeur dans ce processus.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Arts visuels","details":["Peinture","Histoire / Mouvements"]}]},{"source_id":"garnier:887","title":"L’Esculape et son art à la Renaissance Le discours préfaciel dans les ouvrages français de médecine (1528-1628)","authors":["Koźluk, Magdalena"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443800"],"subtitle":"","description":"Ce livre étudie le discours préfaciel des ouvrages médicaux en français (1528-1628). L’auteur adopte une approche pluridisciplinaire, à la croisée des recherches sur la rhétorique et sur l’histoire du livre et étudie les aspects culturels et idéologiques de l’écriture médicale. La préface constitue un témoignage sur la situation de la médecine au xvie siècle et devient le lieu où les esculapes débattent de leurs propres méthodes et évaluent leur savoir en se livrant à une défense de la médecine savante.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]}]},{"source_id":"garnier:19570","title":"L’Extase et ses paradoxes Essai sur la structure narrative du Tiers Livre","authors":["Zhiri, Oumelbanine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458125"],"subtitle":"","description":"Le Tiers Livre déroute autant qu'il amuse, le récit passant abruptement d’une aventure à l’autre. Face au chaos apparent du texte, cette étude s'efforce, comme Pantagruel et Panurge, d'interpréter les signes et de suivre le cheminement du sens, entrant ainsi dans un jeu littéraire et philosophique prodigieux.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:125991","title":"L’Histoire du rémora À quoi voulez-vous croire ?","authors":["Jouteur, Isabelle","Fourdrinoy, Johan","Rousseaux, Germain"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406148821"],"subtitle":"","description":"Un poisson minuscule capable d’immobiliser les navires en mer, en vertu d’un pouvoir magique. Et une bataille célèbre où il fit rage : Actium. Telle fut la légende qui circula sur le rémora avant que le mystère ne soit résolu par une équipe de chercheurs. Ce livre en raconte l’histoire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Histoire des sciences et techniques","details":[]}]},{"source_id":"garnier:19539","title":"L’Homosexualité dans l’imaginaire de la Renaissance","authors":["Poirier, Guy"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454998"],"subtitle":"","description":"De l’analyse des « discours de la condamnation » à l’étude de la construction de la légende d’Henri III, cet essai propose une synthèse sur la représentation de l’homosexualité à la Renaissance dans les discours religieux, juridique, médical, ethnographique, pamphlétaire et littéraire.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:19500","title":"L’Inquiétante étrangeté - Montaigne : la pierre, le cannibale, la mélancolie","authors":["Pot, Olivier"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458088"],"subtitle":"","description":"Le présent ouvrage propose une enquête phénoménologique de la mélancolie dans les Essais, en recourant aux ressources de la linguistique, de l’onomastique ou encore de la psychologie. Michel de Montaigne, en s’ouvrant à l’inquiétante étrangeté, invente une culture de la mélancolie et une anthropologie moderne.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19479","title":"L’Ombre discourante de Marie de Gournay","authors":["Franchetti, Anna Lia"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451744"],"subtitle":"","description":"Cet ouvrage analyse les principaux noyaux thématiques de l’œuvre de Marie de Gournay et leur métamorphose au fil des éditions. Il s’en dégage le portrait d'une intellectuelle anticonformiste qui se bat pour sauvegarder son droit à la pensée libre, sans se départir d’un vif sens de l’humour.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19496","title":"L’Ontologie de la contradiction sceptique - Pour l’étude de la métaphysique des Essais","authors":["Miernowski, Jan"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455957"],"subtitle":"","description":"L’analyse de la métaphysique des Essais révèle une conception de l'être fondamentalement négative. Si la plénitude de l’écriture ne réussit pas à compenser le doute montaignien, le discours parvient néanmoins à sonder lucidement le vide de l’être, dans un défi intellectuel toujours renouvelé.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:8460","title":"L’Oralité perdue Essais d’histoire des pratiques lettrées (Brésil, xvie-xixe siècle)","authors":["Daher, Andrea"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812446542"],"subtitle":"","description":"Que dit la parole sauvage dans l'écriture ? Cet ouvrage montre comment les récits des missionnaires sur les Indiens du Brésil des xvie et xviie siècles représentent l'oralité indigène et met en évidence les multiples politiques des langues dans les textes et leurs appropriations jusqu'au xxe siècle.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Histoire culturelle et sociale","details":[]},{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Discours et pragmatique"]}]},{"source_id":"garnier:141758","title":"L’Orient au peigne fin Les Observations de Pierre Belon (1553), récit de voyage naturaliste","authors":["Privat, Juliette"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406177197"],"subtitle":"","description":"Cet ouvrage permet de redécouvrir le récit de voyage atypique de Pierre Belon, les Observations de plusieurs singularitez (1553). Mêlant littérature viatique et histoire naturelle, ce texte jette un regard curieux sur l’Orient, tout en façonnant une autorité scientifique nouvelle à la Renaissance.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19541","title":"L’Écriture de la méditation chez Jean de Sponde","authors":["Lardon, Sabine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459238"],"subtitle":"","description":"Conduit à partir de l'étude de passages précis du texte, cet ouvrage révèle la spécificité et la valeur littéraire des Méditations sur les Pseaumes, l'un des quatre grands recueils de méditations protestantes en prose de la fin du xvie siècle. Jean de Sponde s’y révèle à la fois exégète, prédicateur et poète.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19655","title":"L’Œuvre de Pierre Charron - (1541-1603) Littérature et théologie de Montaigne à Port-Royal","authors":["Belin, Christian"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452550"],"subtitle":"","description":"Cette étude interroge la cohérence de l’œuvre de Pierre Charron, fondée sur la notion de sagesse. Il tente de concilier une vision humaniste avec un discours démystificateur qui emprunte à saint Augustin. La réception contrastée de son œuvre éclaire l'histoire des idées en amont de l'œuvre pascalienne.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:60243","title":"L’Œuvre poétique de Dominique Fourcade Un lyrisme lessivé à mort du réel","authors":["Fourcaut, Laurent"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406085713"],"subtitle":"","description":"Dominique Fourcade est l’un des grands poètes d’aujourd’hui. Son écriture, dialoguant avec tous les arts, a pour objet le réel, qu’elle saisit en se lavant de tous les poétismes et en travaillant réflexivement et lyriquement le corps de la langue. Cet ouvrage propose un parcours complet de son œuvre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19553","title":"Marc-Claude de Buttet (1529/31-1586) L’honneur de la Savoie","authors":["Stacey, Sarah Alyn"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459276"],"subtitle":"","description":"Ami de la Pléiade, élève de l'illustre Jean Daurat, protégé de la fille de François Ier, Marguerite de France, de son vivant Marc-Claude de Buttet (1529/31-1586) était reconnu comme le premier poète de son pays, «l'honneur de la Savoye». Panégyriste d'abord à la cour française, ensuite à la cour savoyarde, il fut connu surtout pour ses deux recueils de poésies, Le Premier Livre des odes... (1560) et L'Amalthée (1575). Ses vers mesurés lui procurèrent la réputation d'être un des poètes les plus innovateurs de son époque. Et pourtant, comme bien de ses contemporains, après sa mort il est vite tombé dans l'oubli. Le présent ouvrage propose une étude historique qui nous permettra non seulement de mieux connaître la vie de Buttet mais de mieux comprendre le contexte culturel dans lequel il composait ses vers et les influences sur sa poésie. Nous espérons surtout donner un aperçu de l'importance de l'activité littéraire en Savoie au {ptm}XVI{/ptm}e siècle, une activité longtemps ignorée et toujours négligée.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:81243","title":"Marcel Pagnol, classique-populaire Réflexions sur les valeurs d'une œuvre intermédiale","authors":["Brun, Marion"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406086000"],"subtitle":"","description":"Ce livre propose une étude inédite sur un auteur négligé par la recherche universitaire : Marcel Pagnol. À partir de son cas, ce travail interroge les processus de légitimation et de construction du canon. Cette recherche explore les paradoxes d’un auteur qui relève de la middlebrow culture.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:100115","title":"Marguerite Yourcenar, une femme à l’Académie - Malgré eux, malgré elle… Édition revue et augmentée","authors":["Brémond, Mireille"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406115380"],"subtitle":"","description":"Cet ouvrage est une enquête ni partisane ni passionnelle sur l’élection de Marguerite Yourcenar à l’Académie française, première femme à recevoir cet honneur : campagne médiatique, long cheminement qui a conduit à cette consécration, stratégie mise en œuvre par l’intéressée.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:68430","title":"Marguerite Yourcenar, une femme à l’Académie Malgré eux, malgré elle…","authors":["Brémond, Mireille"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406071945"],"subtitle":"","description":"Cet ouvrage est une enquête ni partisane ni passionnelle sur l’élection de Marguerite Yourcenar à l’Académie française, première femme à recevoir cet honneur : campagne médiatique, long cheminement qui a conduit à cette consécration, stratégie mise en œuvre par l’intéressée.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:138030","title":"Meschonnic lecteur de Mallarmé Le silence et la voix","authors":["Mourey, Laurent"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406167211"],"subtitle":"","description":"La présence de Mallarmé n’a cessé de s’accroître dans l’œuvre théorique du poète Henri Meschonnic (1932-2009). S’attachant aux enjeux croisés des deux œuvres, l’étude explore les lignes de force d’une réception critique qui s’inscrit dans une approche de la poésie par l’oralité et le rythme.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19552","title":"Mnémosyne Ronsard, une poétique de la mémoire","authors":["Dauvois, Nathalie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457708"],"subtitle":"","description":"Si la poésie ronsardienne s'inscrit dans une tradition rhétorique bien établie confondant le louable et le mémorable, c’est dans le dialogue qu’elle instaure avec les œuvres antiques, leurs mythes, mais aussi leurs voix et leur style qu’elle forge sa propre poétique de la mémoire, sous le signe de la polyphonie.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19683","title":"Monstres et chimères - Montaigne, le texte et le fantasme","authors":["Garavini, Fausta"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453939"],"subtitle":"","description":"Cet ouvrage interroge dans Les Essais les espaces où l'écriture accueille les « chimères et monstres fantasques » venant de la profondeur de l'inconscient. La fonction des Essais est en fait de mobiliser le pouvoir rédempteur de la parole raisonnable pour résister à l'assaut des « monstres ».","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19513","title":"Montaigne - La Glose et l’Essai","authors":["Tournon, André"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451966"],"subtitle":"","description":"Dans ce livre il s'agit de décrire l'armature du « nouveau langage » philosophique à l'œuvre dans les Essais, d'en indiquer les antécédents – commentaire humaniste et glose juridique – et de définir le type de vérité qui s'y invente.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19475","title":"Montaigne - L’éveil de la pensée","authors":["Pouilloux, Jean-Yves"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456107"],"subtitle":"","description":"Cette étude s’intéresse au maître à penser paradoxal qu’est Montaigne. Refusant l’intemporalité du sens, cet éveilleur de conscience, souvent provocateur, incite le lecteur à douter et initier un mouvement réflexif qui conduit du postulat d’un sens vers l’expérience jubilatoire de la réflexion.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19486","title":"Montaigne - penseur et philosophe (1588-1988)","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452451"],"subtitle":"","description":"Les études ici réunies annoncent un retour à la pensée philosophique de Montaigne. Elles nous révèlent également l’existence d’une école seiziémiste africaine constituée, formée de littéraires et de philosophes, jeune mais qui, on peut en juger, a déjà à nous apprendre.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19477","title":"Montaigne et les libertins","authors":["Dotoli, Giovanni"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454660"],"subtitle":"","description":"La fortune des Essais semble liée à l’évolution du courant libertin. Malgré le triomphe extérieur de l'ordre moral à la fin du xviie siècle, Michel de Montaigne reste du côté des questionneurs et des penseurs attentifs à l'évolution de la société, contribuant ainsi à la naissance de l'esprit laïque.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19505","title":"Montaigne et Sebond - L’art de la traduction","authors":["Hendrick, Philip"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458392"],"subtitle":"","description":"La traduction de la Theologia Naturalis de Raimond Sebond est une ressource inépuisable pour comprendre comment Michel de Montaigne a développé son propre style et ses propres idées, au sein d’un dialogue constant entre Theologia et les Essais. Les théories de la traductologie révèlent des choix riches de créativité.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Langues et linguistique","subcategory":"Traduction et interprétation","details":["Traduction"]}]},{"source_id":"garnier:19487","title":"Montaigne for ever - L’édition de l’Exemplaire de Bordeaux au début du xxe siècle","authors":["Keffer, Ken"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456503"],"subtitle":"","description":"Cet ouvrage, traduction de la Publication History of the Rival Transcriptions of Montaigne's Essays, retrace le demi-siècle (1868-1933) où les paléographes, les universitaires et les admirateurs inconditionnels des Essais ont rivalisé pour procurer une version « scientifique » de ce livre.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:357","title":"Montaigne manuscrit","authors":["Legros, Alain"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812439414"],"subtitle":"","description":"Édition diplomatique de la totalité des autographes conservés (excepté l'exemplaire de Bordeaux), avec traductions, explications et commentaires: ex-libris, ex-dono et devises de jeunesse, notes du Beuther, arrêts du Parlement, notes de lecture dont celles, inédites, d'un Térence retrouvé, lettres missives, dédicaces. L'illustration montre les permanences et les évolutions du ductus de Montaigne sur une quarantaine d'années, en latin, puis en français, parfois en grec et en italien.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Journaux et récits personnels","details":[]},{"family":"Littérature et études littéraires","subcategory":"Correspondance","details":[]}]},{"source_id":"garnier:19626","title":"Montaigne politique","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458262"],"subtitle":"","description":"Cet ouvrage envisage toutes les facettes de l’engagement politique de Michel de Montaigne, de la place du politique dans son œuvre à son rôle comme acteur politique. Est ainsi mis en évidence le rapport à la fois historique et idéologique entre la politique de son temps et la « production » de ses œuvres.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19497","title":"Montaigne propriétaire foncier","authors":["Marcetteau-Paul, Agnès"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451881"],"subtitle":"","description":"Le « Terrier de Montaigne » documente le mécanisme d'ascension sociale et nobiliaire qui anime la famille Eyquem dans la période précédant la naissance de Michel de Montaigne. Il ouvre des champs d'investigation dans les domaines de l'histoire littéraire et des recherches sociales, onomastiques et toponymiques.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Histoire-Géo","subcategory":"Histoire culturelle et sociale","details":[]}]},{"source_id":"garnier:351","title":"Montaigne traducteur de la Théologie naturelle Plaisantes et sainctes imaginations","authors":["Habert, Mireille"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443763"],"subtitle":"","description":"L'étude de la traduction par Montaigne de la Theologia naturalis de Raymond Sebond permet de voir en œuvre, dès 1569, une attitude critique originale qui pourrait bien être le premier exemple du fidéisme de l'auteur des Essais. La traduction de cet ouvrage qui, sous son titre de Théologie naturelle, masque mal son caractère véritable d'apologie de la religion chrétienne, révèle Montaigne aussi réticent envers la démarche de Raymond Sebond que respectueux de la foi qui en irrigue le discours.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Langues et linguistique","subcategory":"Traduction et interprétation","details":["Traduction"]}]},{"source_id":"garnier:19801","title":"Montaigne Une vie, une œuvre - 1533-1592","authors":["Frame, Donald"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453267"],"subtitle":"","description":"Voici, enfin traduite en français, la première biographie de Montaigne, publiée en anglais aux Etats-Unis en 1965. Elle n'a pas été remplacée et reste la biographie la plus complète et la mieux informée. Elle est munie d'une table analytique, d'une bibliographie mise à jour, d'index, qui rendent sa consultation aisée et en font une source de renseignements inépuisables sur Montaigne et son temps. Cette biographie est l'œuvre du grand montaigniste américain Donald Frame, récemment décédé.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:3260","title":"Musica humana La musique dans la pensée de l’humanisme italien","authors":["Malhomme, Florence"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812411106"],"subtitle":"","description":"À la Renaissance se substitue au paradigme de la musica mundana une musique proprement humaine, qui renoue un dialogue avec l'âme, retisse un lien vivant avec la parole et l'éthique, assure la revalorisation de la corporéité, se faisant l'expression d'un chant capable de dire tout l'humain.","from":[{"family":"Art / Culture","subcategory":"Musique","details":["Classique et opéra"]}],"paths":[{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]},{"source_id":"garnier:19636","title":"Musiciens au temps des derniers Valois - (1547-1589)","authors":["Handy, Isabelle"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455322"],"subtitle":"","description":"Au temps des derniers Valois (1547-1589), Paris est une ville en pleine effervescence, un centre littéraire et universitaire où se côtoient artistes, artisans, humanistes, imprimeurs installés dans le quartier de la Sorbonne. Séjournant fréquemment dans la capitale du royaume, les souverains s'attachent à développer une cour brillante nourrie de culture et d'art. De nombreux «gens de mestier» sont ainsi appelés à évoluer dans les cercles du pouvoir. Si la notoriété des peintres, sculpteurs ou architectes est désormais reconnue, celle des musiciens reste toujours à démontrer pour cette époque réputée pauvre en sources historiques originales. Cet ouvrage, réalisé sur une base documentaire conséquente, invite ainsi à réhabiliter une période mal connue de l'histoire de la musique. Du musicien de la corporation au musicien de cour, des centaines de parcours originaux ont été analysés, nous éclairant sur l'ensemble des mentalités, des modes de vie, sur le métier de musicien au XVIe siècle, sa fonction à la cour et à la ville. Le quotidien de ces artistes se révèle à travers un domaine rejeté dans l'ombre poussiéreuse: les manuscrits et les minutes notariées. Mais quelle part active ont pris ces bâtisseurs de l'ère baroque dans une société en pleine mutation?","from":[{"family":"Art / Culture","subcategory":"Musique","details":["Classique et opéra"]}],"paths":[{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:138636","title":"Musique et juste milieu à l'âge humaniste et classique","authors":["Malhomme, Florence"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406172789"],"subtitle":"","description":"À l’âge humaniste et classique, le juste milieu, avec ses notions de mesure, justesse et harmonie, suscite un dialogue entre musique, rhétorique et éthique, incluant les beaux-arts et les arts du corps. Valeur intemporelle, cette sagesse de l’élégance nous invite à retrouver le sens de la mesure.","from":[{"family":"Art / Culture","subcategory":"Musique","details":["Classique et opéra"]}],"paths":[{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]},{"source_id":"garnier:19709","title":"Méditations sur les Psaumes","authors":["Duplessis-Mornay, Philippe"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458309"],"subtitle":"","description":"Cet ouvrage réunit les méditations que Philippe Duplessis-Mornay a consacrées aux psaumes durant sa vie. Il pratique ce genre en vogue dans les cercles réformés comme un mode d'explication de l'Écriture et comme un genre littéraire dévot. Cette édition en éclaire les enjeux religieux, historique et littéraire.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Textes sacrés et exégèse","Spiritualité"]}]},{"source_id":"garnier:19746","title":"Méditations sur les Pseaumes","authors":["Sponde, Jean de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456305"],"subtitle":"","description":"Dédiées au roi de Navarre, les méditations de Jean de Sponde, alors toujours protestant et vivant intensément sa foi, se font l’écho des misères de l’Église et du peuple des fidèles. Le riche paratexte inscrit l’œuvre dans l'histoire politique, juridique, religieuse et littéraire de son temps.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Textes sacrés et exégèse","Spiritualité"]}]},{"source_id":"garnier:87","title":"Mémoire de la mémoire Jacques Roubaud et la lyrique médiévale","authors":["Puff, Jean-François"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812442162"],"subtitle":"","description":"L’œuvre de Roubaud se distingue par le rapport qu’elle entretient avec la tradition poétique. À égale distance de la volonté de rupture et du désir de restauration, le poète choisit un modèle aussi glorieux qu’éloigné, celui du grand chant d’amour des troubadours, dont il fait sienne la poétique. La mise en oeuvre de cette poétique n’est pourtant pas évidente à saisir dans la diversité de son œuvre. Ce sont les principes, les fins, et les résultats concrets d’un tel rapprochement que ce livre s’attache à exposer, révélant ainsi un mode spécifique de déploiement du nouveau, qui fait l’unité de l’entreprise poétique de Roubaud. Compte tenu d’une mise en situation historique, ce programme se réalise en suivant le double fil d’une « monstration » de la forme et d’une élucidation du sens formel de l’œuvre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:136858","title":"Mémoire de soi, mémoire d’un règne Anne de Bretagne et Louise de Savoie","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406170310"],"subtitle":"","description":"Anne de Bretagne et Louise de Savoie ont mobilisé des outils de communication visuels et textuels pour légitimer l’exercice d’un pouvoir au féminin. Ces traces mémorielles, conçues au seuil de la Renaissance, construisent l’image de deux « femmes célèbres » dont l’aura s’assombrit au xixe siècle.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:19550","title":"Nicolas de Harlay sieur de Sancy (1546-1629) L’antagoniste d’Agrippa d’Aubigné Étude biographique et contexte pamphlétaire","authors":["Schrenck, Gilbert"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455032"],"subtitle":"","description":"L’image de l'apostat sans scrupules forgée par Agrippa d'Aubigné est restée durablement attachée au nom de Nicolas de Harlay. À la lumière de nombreux documents contemporains, cette étude biographique restitue le rôle historique essentiel qu'il joua dans la vie politique et littéraire de la fin du xvie siècle.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Histoire-Géo","subcategory":"Biographie","details":["Historique"]}]},{"source_id":"garnier:96911","title":"Origine, mémoire et recyclage du réel - dans l’œuvre narrative de François Bon","authors":["Portugais, Daniel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406106319"],"subtitle":"","description":"Cette étude s’intéresse à trois dimensions du contemporain que l’œuvre de François Bon interroge incessamment : l’origine, la mémoire et la place qu’occupe le réel dans un monde où l’incertain a progressivement remplacé les formes littéraires anciennes.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19873","title":"Ovide, figures de l’hybride Illustrations littéraires et figurées de l’esthétique ovidienne à travers les âges","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455193"],"subtitle":"","description":"Plus que des êtres soumis à la métamorphose, les poèmes d'Ovide exhibent des créatures hybrides. Ces études analysent cette hybridité, source de mélanges génériques et vecteur de réflexion philosophique. Elles révèlent en outre la fortune de ce concept à travers les siècles et les genres littéraires.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19810","title":"Par élévation d’esprit Antoine Héroët Le poète, le prélat et son temps","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451782"],"subtitle":"","description":"Ce volume révise l’image convenue d’Antoine Héroët véhiculée par une critique souvent peu attentive à son originalité. Les contributions éclairent l'œuvre du poète et ses liens avec les arts visuels et la musique. Elles étudient ses multiples rapports avec ses contemporains, à la fois comme prélat et écrivain.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:159418","title":"Paradis perdus Une étude comparée littérature-musique","authors":["Léon, Sarah"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406201014"],"subtitle":"","description":"Ce travail comparatiste met en regard des œuvres littéraires (Nelly Sachs, Philippe Jaccottet, Pascal Quignard) et musicales (Philippe Hersant, Olivier Greif) autour des notions croisées de l’expérience de la perte et du travail de la mémoire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]},{"source_id":"garnier:792","title":"Paul Claudel et les spectacles populaires Le paradoxe du pantin","authors":["Fleury, Raphaèle"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812444487"],"subtitle":"","description":"À travers une enquête sur les contacts de Claudel avec les spectacles populaires et l'analyse des mises en œuvre qu'il imagine, cet ouvrage montre que le dramaturge réinvestit symboliquement ces formes, mais aussi qu'il les utilise pour une plus grande efficacité de son théâtre. L'adresse à la salle et le spectaculaire témoignent de la confiance de l'auteur catholique dans la capacité de la matière à véhiculer le sens. Mais la séduction qu'ils exercent fait courir le risque d'un rapport idolâtre au spectacle, risque que Claudel met en scène et s'attache à contrôler.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Dramaturgie / Théorie"]}]},{"source_id":"garnier:3253","title":"Paul Claudel, le nô et la synthèse des arts","authors":["Nishino Saigusa, Ayako"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812411007"],"subtitle":"","description":"Pendant son séjour diplomatique au Japon de 1921 à 1927, Paul Claudel rencontre le nô, une forme du théâtre traditionnel. Il y découvre ce qu'il imaginait pour une nouvelle forme de la synthèse des arts. Ce livre éclaire la manière originale dont il interprète et métamorphose le nô dans sa propre création.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Spectacle et arts vivants","details":["Dramaturgie / Théorie"]}]},{"source_id":"garnier:19833","title":"Plutarchus redivivus? - La Boétie et sa réception en Europe","authors":["Panichi, Nicola"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812457821"],"subtitle":"","description":"Habent sua fata libelli. L'histoire de la réception de la Servitude volontaire, pamphlet «scandaleux» et «sulfureuxégf; d'Etienne de la Boétie, est presque unique dans le panorama de la philosophie politique européenne et extraeuropéenne. La masse des traductions dans les diverses langues en témoigne (latin, italien, allemand, belge, hollandais, norvégien, suédois, danois, espagnol, portugais, roumain, russe, serbo-croate, anglais, américain, japonais...). De l'anonymat au bûcher, la Servitude volontaire a noué son destin avec les moments historiques les plus significatifs de l'âge moderne, entendu comme histoire de l'émancipation humaine et de sa liberté: la révolution américaine, la révolution française, la révolution napolitaine de 1799, les luttes ouvrières à Lyon et à Paris de 1835, la révolution de 1848, la libération du nazi-fascisme. Le pamphlet de La Boétie est le seul ouvrage du XVIe siècle qui apparaisse dans la Lijst der aan den verkoop onttrokken en verboden boeken in België. Mais au-delà de la contingence historique, le message laboétien est la reprise de l'éternelle exhortation de l'esprit sain, individuel et collectif: se libérer des chaînes. Un message adressé à tous ceux qui ne veulent pas devenir pectora caeca. Cet ouvrage a été publié en 1999 aux éditions Vivarium (Naples) dans la collection de l'Istituto italiano per gli Studi Filosofici, série «Dalla Rivoluzione francese al Risorgimento italiano» dirigée par Anna Maria Rao. Il portait le titre Plutarchus redivivus? La Boétie e i suo interpreti et était suivi dans l'édition italienne d'un fac-similé de la version italienne du Discours de la Servitude volontaire de Cesare Paribelli publiée à Naples en 1799.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:6133","title":"Pour une vie de mon père. Tome I Rétrospective, 1899-1919","authors":["Ponge, Armande"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812448263"],"subtitle":"","description":"Grâce à de nombreuses archives familiales inédites - correspondances, manuscrits datés, agendas et photographies -, cet ouvrage, première pierre d'un monument à la mémoire de Francis Ponge, retrace les vingt premières années de sa vie, dont quatre de guerre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:87066","title":"Pour une vie de mon père. Tome II Rétrospective, 1919-1939","authors":["Ponge, Armande"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406094234"],"subtitle":"","description":"Grâce à de nombreuses archives familiales inédites – correspondances, manuscrits, carnets et photographies – cet ouvrage, deuxième tome d'un monument élevé à la mémoire de Francis Ponge, retrace ses années d'entre-deux-guerres.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:111626","title":"Pour une vie de mon père. Tome III Rétrospective, 1940-1942","authors":["Ponge, Armande"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406132677"],"subtitle":"","description":"Grâce à de nombreuses archives familiales inédites – correspondances, manuscrits, carnets et photographies, – cet ouvrage, troisième tome pour un monument élevé à la mémoire de Francis Ponge, retrace ses années sous l’occupation allemande, de 1940 à 1942.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:134763","title":"Pour une vie de mon père. Tome IV Rétrospective, 1943-1945","authors":["Ponge, Armande"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406166276"],"subtitle":"","description":"Grâce à de nombreuses archives familiales inédites – correspondances, manuscrits, carnets et photographies –, cet ouvrage, quatrième tome pour un monument élevé à la mémoire de Francis Ponge, retrace ses années sous l’occupation allemande et l’immédiat après-guerre, de 1943 à 1945.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:19622","title":"Poésie encyclopédique et kabbale chrétienne Onze études sur Guy Le Fèvre de La Boderie","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454363"],"subtitle":"","description":"Les onze études réunies dans ce volume tentent de cerner les choix poétiques et religieux de Guy Le Fèvre de La Boderie. Poète et orientaliste, cet humaniste s’employa à mettre sa poésie, d'inspiration fortement nationale, au service d'une apologétique catholique teintée de kabbale et de ficinisme.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:123215","title":"Poésie et Musique au temps de Louis XII","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406146735"],"subtitle":"","description":"Et si l'on pouvait retrouver des pièces chantées dans les corpus poétiques ? Réinterpréter la place de la poésie et relire le théâtre en analysant autrement leur articulation à la musique ? Littéraires et musicologues étudient dans ce volume les liens entre poésie et musique autour de 1500.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:47925","title":"Poésies complètes","authors":["La Boétie, Étienne de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406071433"],"subtitle":"","description":"L’ouvrage contient une édition des poésies d’Étienne de La Boétie, les poésies latines, texte et traduction, et les vers français publiés par Montaigne. Sont jointes les poésies latines de Scaliger dédiées à La Boétie, ainsi que les textes de Montaigne et de Baïf se rapportant à La Boétie.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}]},{"source_id":"garnier:19848","title":"Poétique du secret - Paradoxes et maniérisme","authors":["Tripet, Arnaud"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452109"],"subtitle":"","description":"La présente étude s'interroge sur les qualités expressives du secret tant en peinture qu'en littérature. Les exemples retenus vont du paysage chinois aux jeux de masques vénitiens, des anamorphoses de Hans Holbein aux nus, voilés ou non, de Diego Vélasquez. Cet essai s’accompagne de planches illustrées.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Arts visuels","details":["Peinture"]}]},{"source_id":"garnier:19568","title":"Poétique et pratique dans les Poemes de Jean-Antoine de Baïf","authors":["Vinestock, Elisabeth"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453823"],"subtitle":"","description":"Poète éminent et fécond du xvie siècle, Jean-Antoine de Baïf joua un rôle actif dans le développement par la Pléiade d'un nouveau style de poésie. Cette lecture d'ensemble des neuf livres des Poèmes met en lumière leur extrême variété et leur structure, tout en explorant les thèmes directeurs de cette œuvre.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:6338","title":"Poétiques du voyage aérien dans la littérature","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812447372"],"subtitle":"","description":"Cette étude interroge, de l'Occident à l'océan indien, les mythes et les représentations littéraires et cinématographiques du voyage céleste à travers un corpus méconnu, comportant récits d'aventures, contes, productions scéniques et voyages imaginaires.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:19724","title":"Premières œuvres de piété De la saincte philosophie Méditation sur l'Oraison dominicale Le Cantique d'Ezéchias Méditation sur les pseaumes","authors":["Du Vair, Guillaume"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455056"],"subtitle":"","description":"Les méditations de Guillaume Du Vair constituent un reflet des mentalités religieuses au moment du renouveau spirituel catholique qui suit le concile de Trente. Mais cette œuvre de piété se distingue des publications de la fin du règne d’Henri III par l’écriture et le ton personnels que leur auteur y développe.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Textes sacrés et exégèse","Spiritualité"]}]},{"source_id":"garnier:13095","title":"Privilèges de librairie en France et en Europe xvie-xviie siècles","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406059851"],"subtitle":"","description":"À l’intersection de plusieurs disciplines – histoire du livre, histoire du droit, histoire de la littérature et histoire de l’art –, les contributions réunies dans cet ouvrage proposent des chemins de lecture pour aborder les privilèges de librairie, en France et en Europe aux xvie et xviie siècles.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Médias et communication","subcategory":"Bibliothèques et documentation","details":[]}]},{"source_id":"garnier:5111","title":"Présence critique de Gaëtan Picon Dans l’ouverture de l’œuvre","authors":["Maillard Despont, Aurélia"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812433269"],"subtitle":"","description":"Au tournant des années soixante, Gaëtan Picon s’éloigne d’André Malraux pour affirmer ses propres valeurs. Quittant la critique littéraire pour la critique d’art, il opère une conversion qui, inscrite dans un contexte de mainmise formaliste, intervient en réponse à son questionnement esthétique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:92538","title":"Prêcher la mort à l’époque moderne Regards croisés sur la France et l’Angleterre","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406100294"],"subtitle":"","description":"Se fondant sur une approche pluridisciplinaire et comparative entre histoire littéraire, histoire culturelle et histoire religieuse, ce volume présente une cartographie contrastée de la prédication chrétienne autour de la mort dans l’Europe des deux Réformes, marquée par les dissensions religieuses.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]}]},{"source_id":"garnier:130975","title":"Renaissance de Giono La reconstruction de l’auteur après la Seconde Guerre mondiale","authors":["Marion, Annabelle"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406159063"],"subtitle":"","description":"Cet ouvrage explore la reconstruction de Giono au lendemain de la guerre et des épreuves qui en ont résulté. À partir de ce cas, il interroge la façon dont se fait, se défait et se refait un auteur, dans une interaction constante avec les réactions du public et les évolutions du champ littéraire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:132671","title":"Renouer avec la terre extatique Essai de sensopoétique chez J.M.G. Le Clézio","authors":["Feyereisen, Justine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406165231"],"subtitle":"","description":"Ouvrant un nouveau champ critique à la croisée de la linguistique textuelle et de la philosophie, cet essai propose de raviver le pouvoir incantatoire de la littérature par une poétique des sens – une sensopoétique – depuis l’œuvre intermédiale de J.M.G. Le Clézio.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:186","title":"Roberval, la Damoiselle et le Gentilhomme Les Robinsons de Terre-Neuve","authors":["Bideaux, Michel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443664"],"subtitle":"","description":"Faisant voile vers le Canada (1542), Roberval a-t-il abandonné sur une île déserte un couple qui lui aurait désobéi? Au silence des documents historiques s'oppose le babil des textes littéraires. Trois versions de l'affaire en trente ans: une nouvelle de l'Heptaméron, une histoire tragique (Belleforest), un récit de Thevet. Offrant ces textes à la lecture, on a tenté de démêler leurs filiations pour observer comment le jeu de la fiction aboutit à cette étonnante floraison.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:19627","title":"Rome franciscaine Essai sur l’histoire de l’éloquence dans l’Ordre des Frères Mineurs au xvie siècle","authors":["Mouchel, Christian"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452758"],"subtitle":"","description":"Abordant l'étude des Frères Mineurs au miroir de ses orateurs, cet ouvrage apporte un éclairage novateur sur l'éloquence religieuse au xvie siècle. Il permet de mieux comprendre l’histoire d’un ordre qui a voulu rester le ferment de l'Église romaine, de son rôle de soutien de la papauté à ses divisions internes.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]}]},{"source_id":"garnier:19649","title":"Royaume de Fémynie Pouvoirs, contraintes, espaces de liberté des femmes, de la Renaissance à la Fronde","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456565"],"subtitle":"","description":"La féminisation de la scène publique est une caractéristique prépondérante de la Renaissance. Ces contributions étudient plusieurs de ces figures et permettent de comprendre comment les arts traduisaient les relations complexes et les enjeux politiques et symboliques à l'œuvre dans une société en pleine mutation.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:19581","title":"Saint-Amant et la Normandie littéraire Études réunies à la mémoire de Jacques Bailbé","authors":["Bailbé, Jacques"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455445"],"subtitle":"","description":"Les articles ici réunis sont autant de regards portés sur la personnalité multiple de Saint-Amant. Ils constituent une interrogation sur la modernité de son esthétique protéiforme. Ce volume convie ainsi à une réflexion sur la vie des formes, illustrée par le foisonnement d'une imagination intarissable.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:8360","title":"Sans oublier Malraux","authors":["Larrat, Jean-Claude"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812447730"],"subtitle":"","description":"Cet ouvrage étudie la part active qu'André Malraux a prise aux idées de son siècle : bergsonisme, nietzschéisme, populisme socialiste avant 1945 ; puis à l'effervescence des sciences humaines : « psychologie des profondeurs », ethnologie, poétique, rhétorique, etc.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19619","title":"Savoir de la nature et poésie des choses Lucrèce et Épicure à la Renaissance italienne","authors":["Gambino Longo, Susanna"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812459191"],"subtitle":"","description":"Cet ouvrage analyse l’influence de la redécouverte de Lucrèce et de la doctrine épicurienne sur la pensée humaniste, à la fois sur les plans éthique et scientifique. Mais Lucrèce reste surtout un modèle rhétorique et littéraire prouvant que la poésie peut encore assurer la connaissance philosophique et scientifique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19840","title":"Shakespeare et l’architecture Nouvelles inventions pour bien bâtir et bien jouer","authors":["Cunin, Muriel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456862"],"subtitle":"","description":"À partir de l'analyse de pièces de William Shakespeare, cette étude se propose d'examiner les liens unissant son théâtre à l'architecture de l'époque élisabéthaine. En questionnant les idéaux humanistes, elle pose sans cesse la question de la forme et fait naître la vision d'une architecture de l'oscillation.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Architecture","details":["Histoire / Patrimoine"]}]},{"source_id":"garnier:19544","title":"Signe(s) d’Amante L’Agencement des Evvres de Louïze Labé Lionnoize","authors":["Martin, Daniel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453366"],"subtitle":"","description":"Dans cet ouvrage, est analysée, avec virtuosité, la « belle forme de livre » que Louise Labé a donnée à son unique recueil. Fondant sa cohérence sur son hétérogénéité, l’œuvre de la poétesse lyonnaise s'organise suivant un savant et dense réseau d'échos, d'effets de rappel, d'interférences, de parallélismes.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:107734","title":"Sous le signe de la colère Henri Michaux et Louis-Ferdinand Céline","authors":["Hachette, Pauline"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406126706"],"subtitle":"","description":"Passion outrée et volontiers opposée au logos, la colère dévoile en réalité nombre de ses qualités lorsqu’on la saisit en tant que processus de signification passionnelle. Les styles de colère de Céline et Michaux, aussi ostentatoires qu’antinomiques, en constituent de puissantes manifestations.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19599","title":"Structures sonores de l’humanisme en France De Maurice Scève, Delie, object de plus haulte vertu (Lyon, 1544) à Claude Le Jeune, Second livre des Meslanges (Paris, 1612)","authors":["Bonniffet, Pierre"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812458200"],"subtitle":"","description":"La thèse propose une méthode d'analyse des poèmes du {ptm}XVI{/ptm}e siècle et des trois éléments fusionnés dans les chanons (Phonèmes, musiques et chant), selon les trois étapes (invention, disposition et élocution) que les écoliers apprenaient durant le trivium. La fonction des trois éléments du corps sonore a beaucoup évolué dans le champ sonore en soixante ans. La parole, de sujet, devient objet de la musique. La musique, malgré les efforts du psaume et de la poésie mesurée, s'affranchit de la parole et de ses référents. Le chant, dans ce divorce, s'émancipe à son tour et invente ses propres référents.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]},{"source_id":"garnier:507","title":"Sénèque le Tragique en France (xvie-xviie siècles) Imitation, traduction, adaptation","authors":["Caigny, Florence de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812441059"],"subtitle":"","description":"Modèles de référence dès 1550, les tragédies de Sénèque sont peu à peu contestées dans leur esthétique au xviie siècle sans pour autant cesser d'influencer les dramaturges français. En confrontant théories de l'imitation, réflexions sur le genre tragique et caractéristiques propres au théâtre de Sénèque, le présent ouvrage se propose d'expliquer cette paradoxale présence. Imiter, traduire et adapter: sur un siècle et demi, il retrace l'évolution des formes de cette influence et ses raisons.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:6135","title":"Tempêtes en mer Permanence et évolution d’un topos littéraire (xvie-xviiie siècle)","authors":["Riveline, Éva"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812435591"],"subtitle":"","description":"Cette étude confronte les récits de tempête en mer dans les textes narratifs entre le xvie et le xviiie siècle. Elle montre qu'ils possèdent des qualités littéraires et une profondeur exceptionnelles, suscitant un questionnement à la fois esthétique, éthique et philosophique.","from":[{"family":"Histoire-Géo","subcategory":"Géographie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:104001","title":"Teofilo Folengo en France à la Renaissance « Entendons ce que dict Merlin Cocagne »","authors":["Primot, Carole"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406121794"],"subtitle":"","description":"Du corpus des textes macaroniques français à la traduction anonyme du Baldus, l’Histoire macaronique, en passant par le poète Bérenger de la Tour ou des recueils de facéties, cet ouvrage explore des lectures qui permettent de saisir la diversité de la réception des Macaronées de Teofilo Folengo.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19543","title":"The Renaissance portrait in France and England A Comparative Study","authors":["Bentley-Cranch, Dana"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453052"],"subtitle":"","description":"","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Arts visuels","details":["Peinture","Histoire / Mouvements"]}]},{"source_id":"garnier:19657","title":"Traduction et adaptation en France - à la fin du Moyen Âge et à la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452574"],"subtitle":"","description":"Au Moyen Âge comme à la Renaissance, la culture passe par la traduction : connaître, c’est traduire. Ce volume aborde les enjeux théoriques et méthodologiques de la transposition en moyen français, ainsi que son influence sur l’histoire des idées, l’histoire de la langue et l’esthétique littéraire.","from":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Traduction et interprétation","details":["Traduction"]}]},{"source_id":"garnier:98875","title":"Traduire le mot d’esprit Pour une géographie du rire dans l’Europe de la Renaissance","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406109402"],"subtitle":"","description":"Le volume rassemble dix-neuf contributions qui étudient la circulation, la transmission et l’acculturation des textes facétieux dans l’Europe de la Renaissance. Elles dessinent les contours d’une géographie européenne du rire et décrivent la genèse d’un patrimoine facétieux partagé.","from":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Traduction et interprétation","details":["Traduction"]}]},{"source_id":"garnier:82","title":"Témoigner clandestinement Les récits lazaréens de Jean Cayrol","authors":["Basuyaux, Marie-Laure"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812443602"],"subtitle":"","description":"Les fictions de Jean Cayrol peuvent être envisagées comme le lieu d'une proposition pour la littérature post-concentrationnaire. La poétique imaginée par l'auteur du «romanesque lazaréen», exposée dans des lieux théoriques divers, repose sur un principe implicite que l'étude de ses récits permet seule de saisir : la nécessité pour la fiction d'entretenir une relation de dialogue avec les témoignages des camps. Personnel romanesque, traitement de l'énonciation, configuration narrative, substrat métaphorique : à la manière d'une structure obscure, ce lien gouverne tous les aspects de la fiction. Lui prêter attention permet de mieux comprendre en quoi l'œuvre lazaréenne fonctionne comme un lieu d'articulation entre la littérature concentrationnaire et le Nouveau Roman.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19737","title":"Un Corps, un destin La Femme dans la médecine de la Renaissance","authors":["Berriot-Salvadore, Evelyne"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453465"],"subtitle":"","description":"Cette étude analyse le statut de la femme à la Renaissance à la lumière de la littérature médicale de l’époque, entre héritage médiéval et discours humaniste. Elle est accompagnée de planches médicales, de deux traités médicaux, d’une étude sur les mutilations sexuelles et d’une analyse des « canards criminels ».","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Santé et médecine","subcategory":"Histoire de la santé et de la médecine","details":[]}]},{"source_id":"garnier:19610","title":"Un philosophe libertin dans l’Europe baroque - Giulio Cesare Vanini 1585-1619","authors":["Foucault, Didier"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453281"],"subtitle":"","description":"Au-delà du récit de la vie aventureuse de Giulio Cesare Vanini, cette étude propose une biographie intellectuelle d’un moine au savoir humaniste et engagé dans les débats religieux de son temps. Il élabore une philosophie résolument matérialiste, considérée comme un des premiers témoignages de l'athéisme moderne.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]},{"family":"Histoire-Géo","subcategory":"Biographie","details":["Historique"]}]},{"source_id":"garnier:19843","title":"Une inquisition en Provence - (Apt, 1532)","authors":["Audisio, Gabriel"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454561"],"subtitle":"","description":"Ce procès-verbal nous livre un face à face dramatique entre l'inquisiteur Jean de Roma, dominicain érudit, et un jeune prédicateur vaudois, Pierre Griot. Seul témoignage du synode de Chanforan, il délivre d'importantes informations sur la communauté vaudoise mais aussi sur les méthodes de cet inquisiteur.","from":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Histoire-Géo","subcategory":"Renaissance","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"garnier:13142","title":"Une vie de gloire et de souffrance Le mythe de Beethoven sous la Troisième République","authors":["Gaboriaud, Marie"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406062424"],"subtitle":"","description":"La Troisième République a mystifié Beethoven, en en faisant un personnage doté de valeurs qui fondent alors la construction de l’identité nationale. Ce mythe se déploie dans une vaste littérature beethovénienne, qui emprunte autant à la littérature épique et hagiographique, qu’à la littérature populaire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Histoire / Société"]}]},{"source_id":"garnier:19498","title":"Une vie de Montaigne - ou Le sommaire discours sur la vie de Michel Seigneur de Montaigne (1608)","authors":["Magnien-Simonin, Catherine"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452826"],"subtitle":"","description":"A l'aube du XVIIe siècle, alors que les Essais deviennent un livre à succès, des libraires désireux d'appâter leur clientèle décident de présenter Montaigne avec l'apparat (préface, indices, tables, portrait et vie) réservé aux classiques. Né, sur commande et dans l'anonymat, d'un montage de fragments des Essais, Le Sommaire discours de la vie de Michel, seigneur de Montaigne commence en 1608 une longue carrière: deux siècles et demi durant, il va imposer son Montaigne de légende et étouffer toute légitime curiosité biographique.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"garnier:19518","title":"« En sens agile » - Les acrobaties de l’esprit selon Rabelais","authors":["Tournon, André"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812452000"],"subtitle":"","description":"La déconcertante parade langagière du Tiers Livre marque l'inflexion du roman vers la fantaisie, des boniments aux contorsions exégétiques. L’analyse de la logique insolite du récit de François Rabelais éclaire des aspects hétérodoxes de la spiritualité de la Renaissance comme les audaces philosophiques du rire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:19472","title":"« Je ne suis pas philosophe » Montaigne et la philosophie","authors":["Comte-Sponville, André"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451683"],"subtitle":"","description":"« Je ne suis pas philosophe », écrit Michel de Montaigne dans les Essais. Le présent texte vise à montrer qu'il l'est pourtant, et d'autant plus peut-être qu'il y prétend moins. Il lit les philosophes, les confronte les uns aux autres, et à soi. Il aime la philosophie vivante, enjouée et « folâtre ».","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"garnier:19494","title":"« J’ayme ces mots... » : expressions linguistiques de doute dans les Essais de Montaigne","authors":["Sellevold, Kirsti"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812456541"],"subtitle":"","description":"Les marqueurs de polyphonie et d’évidentialité ont pour fonction de marquer un écart entre le locuteur et ses propos. Cette étude soumet une série de passages-clés des Essais à une analyse linguistique précise afin de mieux saisir, au fond du langage même, le mouvement de la réflexion montaignienne.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]},{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Discours et pragmatique"]}]},{"source_id":"garnier:19839","title":"« Le Texte emprunté » Étude comparée du Narrenschiff de Sebastian Brant et de ses adaptations (1494-1509)","authors":["Metzger-Rambach, Anne-Laure"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812451867"],"subtitle":"","description":"Ce volume offre une nouvelle approche du riche héritage plurilingue du Narrenschiff de Sebastian Brant. La confrontation des traductions latines, françaises et anglaises révèle que l’adaptation dans une autre langue constitue une entrée en écriture et s’avère, à plus d'un titre, une forme de création littéraire.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Œuvres","details":[]}]},{"source_id":"garnier:89676","title":"« Que me servent mes vers ? » La musique chez Ronsard, avec un supplément vocal de 22 chansons","authors":["Girot, Jean-Eudes","Tacaille, Alice"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406093671"],"subtitle":"","description":"Pourquoi Ronsard fait-il mettre en musique ses poèmes des Amours en 1552 ? C’est à cette question que répond l’ouvrage qui se compose d’un essai liminaire et d’une anthologie de 22 chansons enregistrées (dont le « Supplément musical » de 1552) présentées avec un commentaire et une partition.","from":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]},{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]},{"source_id":"garnier:19665","title":"À travers la galerie François Ier","authors":["Joukovsky, Pierre","Joukovsky, Françoise"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812454202"],"subtitle":"","description":"Après de la défaite de Pavie, la galerie de François Ier rétablit symboliquement la figure royale dans toute sa majesté. Cette étude analyse le programme iconographique mis en œuvre pour instaurer un royaume de signes combinant plusieurs niveaux d’interprétation – historique, morale, politique et religieuse.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Art / Culture","subcategory":"Arts visuels","details":["Iconographie"]}]},{"source_id":"garnier:19596","title":"Èthos et Pathos - Le statut du sujet rhétorique","authors":[],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812453892"],"subtitle":"","description":"Ce recueil analyse la présence du sujet dans le discours à travers les catégories mouvantes et conflictuelles de l'éthos et du pathos. Ces notions sont déclinées dans leurs rapports avec la philosophie, la politique, la poésie et la fiction, mais aussi en traversant les époques de Virgile à Charles Baudelaire.","from":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":[]}],"paths":[{"family":"Langues et linguistique","subcategory":"Linguistique","details":["Discours et pragmatique"]}]},{"source_id":"garnier:160945","title":"Éclats de Bataille","authors":["Limousin, Christian"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406190417"],"subtitle":"","description":"Ce recueil présente un choix de travaux que Christian Limousin a consacrés à Georges Bataille, faisant revivre l’homme et sa volonté de « tout renverser », de s’interroger sur l’érotisme, les interdits, la mort. Ils vont à l’essentiel d’une pensée difficile en la rendant concrète et accessible.","from":[{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Analyses d’Auteurs","details":[]}]},{"source_id":"garnier:19776","title":"Œuvres complètes. Tome I Le Jugement poetic de l’honneur femenin","authors":["Bouchet, Jean"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782812455537"],"subtitle":"","description":"Dans ce long poème, Jean Bouchet commémore Louise de Savoie tout en défendant les femmes et en revendiquant leur droit à l'éducation. Cette édition de référence éclaire la poétique de ce grand rhétoriqueur et apporte une contribution importante à la recherche sur les discours de l’époque en faveur des femmes.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]},{"family":"Sciences humaines et sociales","subcategory":"Études de genre","details":[]}]},{"source_id":"garnier:58862","title":"Œuvres complètes. Tome II, 1 Solitaire premier, ou, Discours des Muses, Et de la fureur Poëtique","authors":["Tyard, Pontus de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406078029"],"subtitle":"","description":"Annonçant un vaste projet néoplatonicien traitant, pour la première fois en français, du retour de l’âme humaine vers l’unité perdue en fonction de quatre « fureurs », le Solitaire premier présente la première de ces « fureurs », celle dite poétique, avant de se consacrer aux Muses qui en sont la source.","from":[{"family":"Littérature et études littéraires","subcategory":"Poésie","details":[]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]},{"family":"Littérature et études littéraires","subcategory":"Études littéraires","details":[]}]},{"source_id":"garnier:115174","title":"Œuvres complètes. Tome II, 2 Solitaire second, ou, Discours de la Musique","authors":["Tyard, Pontus de"],"publisher":"Classiques Garnier","platform":"garnier","isbns":["9782406131779"],"subtitle":"","description":"Pontus de Tyard poursuit son exploration des arts avec ce Solitaire second (1555). C’est au tour de la musique d’être le sujet du dialogue. Pontus y tente la première synthèse en langue française des sujets qui animent théoriciens et philosophes de la musique depuis les dernières décennies du xve siècle.","from":[{"family":"Art / Culture","subcategory":"Musique","details":["Classique et opéra"]}],"paths":[{"family":"Art / Culture","subcategory":"Musique","details":["Théorie / Musicologie"]}]}];
